NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Leviticus'

CHAPTERS = {
    1: {
        1: 'Herra kutsui Mooseksen ja puhui hänelle ilmestysmajan sisältä sanoen:',
        2: '"Puhu israelilaisille ja sano heille: Jos joku teistä tahtoo tuoda uhrilahjan Herralle, niin tuokaa uhrilahjanne karjasta, joko nautakarjasta tai lampaista.',
        3: 'Jos hänen uhrilahjansa on nautapolttouhri, tuokoon virheettömän urospuolen. Tuokoon sen ilmestysmajan ovelle, jotta Herran mielisuosio tulisi hänen osakseen.',
        4: 'Laskekoon kätensä polttouhriteuraan pään päälle, niin se on otollinen ja tuottaa hänelle sovituksen.',
        5: 'Teurastakoon mullin Herran kasvojen edessä, ja papit, Aaronin pojat, tuokoot veren ja vihmokoot veren ympäriinsä alttarille, joka on ilmestysmajan ovella.',
        6: 'Nylkeköön polttouhriteuraan ja leikelköön sen määräpaloiksi.',
        7: 'Pappi Aaronin pojat tehkööt tulen alttarille ja pankoot puita tuleen.',
        8: 'Papit, Aaronin pojat, asettakoot palat sekä pään ja rasvan puiden päälle, jotka ovat tulella alttarilla.',
        9: 'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi polttakoon kaiken alttarilla. Se on polttouhri, suloisesti tuoksuva uhri Herralle.',
        10: 'Jos hänen uhrilahjansa, joka on tarkoitettu polttouhriksi, on otettu lampaista tai vuohista, tuokoon virheettömän urospuolen.',
        11: 'Teurastakoon sen alttarin pohjoissivulla, Herran edessä, ja papit, Aaronin pojat, vihmokoot sen veren alttarille ympäriinsä.',
        12: 'Leikelköön sen määräpaloiksi, ja pappi asettakoon ne sekä pään ja rasvan puiden päälle, jotka ovat tulella alttarilla.',
        13: 'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi tuokoon sen kaiken ja polttakoon sen alttarilla. Se on polttouhri, suloisesti tuoksuva uhri Herralle.',
        14: 'Jos hänen uhrilahjansa Herralle on polttouhri linnuista, tuokoon uhrilahjanaan metsäkyyhkysiä tai kyyhkysenpoikia.',
        15: 'Pappi tuokoon sen alttarille, vääntäköön siltä niskat nurin ja polttakoon sen alttarilla, ja puserrettakoon sen veri alttarin seinään.',
        16: 'Hän irrottakoon sen kuvun ruokasulineen ja heittäköön sen alttarin viereen itäpuolelle tuhkaläjälle.',
        17: 'Sitten hän reväisköön linnun auki siipien kohdalta niitä irrottamatta, ja pappi polttakoon sen alttarilla puiden päällä, jotka ovat tulella. Se on polttouhri, suloisesti tuoksuva uhri Herralle."',
    },
    2: {
        1: '"Jos joku tahtoo tuoda Herralle lahjaksi ruokauhrin, olkoon hänen uhrilahjanaan ydinjauhoja, vuodattakoon siihen öljyä ja pankoon sen päälle suitsuketta sekä',
        2: 'vieköön sen papeille, Aaronin pojille. Pappi ottakoon kourallisen näitä jauhoja ja tätä öljyä sekä kaiken suitsukkeen ja polttakoon tämän muistouhrin alttarilla suloisesti tuoksuvana polttouhrina Herralle.',
        3: 'Mutta se, mitä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa. Se on korkeasti pyhää, Herran uhria.',
        4: 'Mutta jos tahdot tuoda ruokauhrilahjan uunissa paistetusta, olkoon uhrinasi ydinjauhoista valmistetut, öljyyn leivotut happamattomat leipäkakut tai öljyllä voidellut happamattomat rieskat.',
        5: 'Jos taas uhrilahjasi on ruokauhri, joka paistetaan leivinlevyllä, olkoon se valmistettu ydinjauhoista, öljyyn leivottu ja happamaton.',
        6: 'Paloittele se palasiksi ja vuodata öljyä sen päälle. Se on ruokauhri.',
        7: 'Jos uhrilahjasi on ruokauhri, joka paistetaan pannussa, valmistettakoon se ydinjauhoista ja öljystä.',
        8: 'Vie näin valmistettu ruokauhri Herralle. Vietäköön se papille. Hän tuokoon sen sitten alttarille.',
        9: 'Pappi uhratkoon ruokauhrista muistouhrin ja polttakoon sen alttarilla suloisesti tuoksuvana uhrina Herralle.',
        10: 'Mutta se, mitä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa. Se on korkeasti pyhää, Herran uhria.',
        11: 'Mitään ruokauhria, jonka te tuotte Herralle, älköön valmistettako happamasta. Älkää polttako uhria Herralle mistään happamasta taikinasta tai hunajasta.',
        12: 'Uutisuhrilahjana saatte tuoda niitä Herralle, mutta älkööt ne tulko alttarille suloiseksi tuoksuksi.',
        13: 'Jokainen ruokauhrilahjasi suolaa suolalla äläkä anna Jumalasi liitonsuolan puuttua ruokauhristasi. Jokaiseen uhrilahjaasi sinun on tuotava suolaa.',
        14: 'Mutta jos tahdot tuoda ensisadosta ruokauhrin Herralle, niin tuo ensisadon ruokauhrinasi tulella paahdettuja tähkiä tai survottuja jyviä tuleentumattomasta viljasta.',
        15: 'Vuodata siihen sitten öljyä ja pane siihen suitsuketta. Se on ruokauhri.',
        16: 'Pappi polttakoon alttariuhriosan survotuista jyvistä ja öljystä sekä kaiken suitsukkeen uhrina Herralle."',
    },
    3: {
        1: '"Jos hänen uhrilahjansa on rauhanuhri nautakarjasta joko härkä tai lehmä, tuokoon virheettömän eläimen Herran eteen.',
        2: 'Laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan oven edustalla. Papit, Aaronin pojat, vihmokoot veren alttarille, sen joka taholle.',
        3: 'Tuokoon rauhanuhrista uhrina Herralle sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan',
        4: 'sekä molemmat munuaiset ja niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta.',
        5: 'Aaronin pojat polttakoot sen alttarilla polttouhrin päällä, joka on polttopuiden päällä tulella, suloisesti tuoksuvana uhrina Herralle.',
        6: 'Jos hän tuo uhrilahjanaan Herralle rauhanuhriksi lampaista ja vuohista urospuolen tai naaraspuolen, niin tuokoon virheettömän eläimen.',
        7: 'Jos hän tuo uhrilahjanaan lampaan, tuokoon sen Herran eteen',
        8: 'ja laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan oven edustalla, ja Aaronin pojat vihmokoot sen veren alttarille joka taholle.',
        9: 'Hän tuokoon rauhanuhrista uhrina Herralle sen rasvan, koko rasvahännän, joka on irrotettava häntänikamista, sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan',
        10: 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta.',
        11: 'Pappi polttakoon sen alttarilla uhriruokana Herralle.',
        12: 'Jos hänen uhrilahjansa on vuohi, tuokoon sen Herran eteen',
        13: 'ja laskekoon kätensä sen pään päälle ja teurastakoon sen ilmestysmajan ovella. Aaronin pojat vihmokoot sen veren alttarille, sen joka puolelle.',
        14: 'Tuokoon siitä uhrilahjanaan Herralle uhriksi sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan',
        15: 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta.',
        16: 'Pappi polttakoon ne alttarilla uhriruokana, suloisesti tuoksuvana uhrina. Kaikki rasva olkoon Herralle tuleva.',
        17: 'Tämä olkoon teille ikiaikainen säädös sukupolvesta sukupolveen, missä asuttekin: mitään rasvaa tai verta älkää siitä syökö."',
    },
    4: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Puhu israelilaisille ja sano: Jos joku erehdyksestä rikkoo jotakin Herran käskyä vastaan ja tekee sellaista, mitä ei saa tehdä,',
        3: 'ja jos voideltu pappi tekee synnin ja saattaa kansan syynalaiseksi, tuokoon tekemänsä synnin tähden virheettömän mullin Herralle syntiuhriksi.',
        4: 'Vieköön mullin ilmestysmajan ovelle Herran eteen ja laskekoon kätensä mullin pään päälle ja teurastakoon mullin Herran edessä.',
        5: 'Voideltu pappi ottakoon mullin verta ja vieköön sen ilmestysmajaan,',
        6: 'kastakoon sormensa vereen ja pirskottakoon verta seitsemän kertaa Herran edessä, pyhäkön esiripun edessä.',
        7: 'Pappi sivelköön verta alttarin sarviin, jolla poltetaan hyvänhajuista suitsutusta Herran edessä ja joka on ilmestysmajassa. Kaiken muun mullin veren hän vuodattakoon ilmestysmajan oven edustalla olevan polttouhrialttarin juurelle.',
        8: 'Kaiken syntiuhrimullin rasvan hän erottakoon siitä pois, sekä sisälmyksiä peittävän rasvan että kaiken sisälmysten rasvan,',
        9: 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta,',
        10: 'samalla tavalla kuin se erotetaan pois rauhanuhrin härästä. Pappi polttakoon ne polttouhrialttarilla.',
        11: 'Mutta mullin nahan ja kaiken lihan sekä pään ja jalat, sisälmykset ja ruokasulan,',
        12: 'koko mullin, hän vieköön leirin ulkopuolelle puhtaaseen paikkaan, johon tuhka heitetään, ja polttakoon sen polttopuiden päällä tulella. Poltettakoon se siinä paikassa, johon tuhka heitetään.',
        13: 'Jos koko Israelin seurakunta tahattomasti tekee synnin seurakunnan sitä tietämättä ja jos he rikkomalla jotakin Herran käskyä vastaan ovat tehneet sellaista, mitä ei saa tehdä, he ovat siten joutuneet syynalaisiksi,',
        14: 'ja jos sitten synti, jonka he ovat tehneet jotakin käskyä vastaan, tulee ilmi, seurakunta tuokoon mullin syntiuhriksi ja vieköön sen ilmestysmajan eteen.',
        15: 'Seurakunnan vanhimmat laskekoot kätensä mullin pään päälle Herran edessä, ja mulli teurastettakoon Herran edessä.',
        16: 'Voideltu pappi vieköön mullin verta ilmestysmajaan.',
        17: 'Pappi kastakoon sormensa vereen ja pirskottakoon sitä seitsemän kertaa Herran edessä, esiripun edessä.',
        18: 'Sivelköön sitten verta alttarin sarviin, joka on Herran edessä ilmestysmajassa. Kaiken muun veren hän vuodattakoon ilmestysmajan oven edustalla olevan polttouhrialttarin juurelle.',
        19: 'Erottakoon siitä pois kaiken rasvan ja polttakoon sen alttarilla',
        20: 'ja tehköön mullille, niin kuin hän teki syntiuhrimullille. Tehköön sille samalla tavalla. Kun pappi on näin toimittanut heille sovituksen, heille annetaan anteeksi.',
        21: 'Vieköön mullin leirin ulkopuolelle ja polttakoon sen, niin kuin hän poltti edellisen mullin. Se on seurakunnan syntiuhri.',
        22: 'Jos kansan johtomies tekee synnin rikkoen tietämättään jotakin Herran, Jumalansa, käskyä vastaan tehden sellaista, mitä ei saa tehdä ja joutuu syynalaiseksi,',
        23: 'ja kun hän sitten tulee tietoiseksi synnistään, tuokoon uhrilahjanaan vuohen, virheettömän urospuolen.',
        24: 'Laskekoon sitten kätensä vuohen pään päälle ja teurastakoon sen siinä paikassa, jossa polttouhriteuraat Herran edessä teurastetaan. Se on hänen syntiuhrinsa.',
        25: 'Pappi ottakoon syntiuhrin verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin. Muun veren hän vuodattakoon polttouhrialttarin juurelle.',
        26: 'Mutta kaiken sen rasvan hän polttakoon alttarilla, samalla tavalla kuin rauhanuhrin rasvan. Kun pappi on näin toimittanut hänelle sovituksen hänen synnistään, se annetaan hänelle anteeksi.',
        27: 'Jos joku kansasta erehdyksessä rikkoo jotakin Herran käskyä vastaan tekemällä sellaista, mitä ei saa tehdä, ja joutuu syynalaiseksi,',
        28: 'ja kun hän sitten saa tietää tehneensä synnin, tuokoon tekemänsä synnin tähden uhrilahjana vuohen, virheettömän naaraspuolen,',
        29: 'ja laskekoon kätensä syntiuhriteuraan pään päälle ja teurastakoon sen polttouhripaikalla.',
        30: 'Pappi ottakoon vuohen verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin. Kaiken muun veren hän vuodattakoon alttarin juurelle.',
        31: 'Pappi irrottakoon kaiken sen rasvan, niin kuin rasva irrotetaan rauhanuhrista, ja polttakoon sen alttarilla suloisena tuoksuna Herralle. Kun pappi on näin toimittanut hänelle sovituksen, hänelle annetaan anteeksi.',
        32: 'Mutta jos hän tuo lampaan syntiuhriksi, niin tuokoon virheettömän naaraan',
        33: 'ja laskekoon kätensä tämän syntiuhriteuraan pään päälle ja teurastakoon sen syntiuhriksi siinä paikassa, missä polttouhrieläin teurastetaan.',
        34: 'Pappi ottakoon syntiuhrin verta sormeensa ja sivelköön polttouhrialttarin sarviin. Kaiken muun veren hän vuodattakoon alttarin juurelle.',
        35: 'Kaiken lampaan rasvan hän irrottakoon, samoin kuin rauhanuhrilampaan rasva irrotetaan, ja pappi polttakoon sen alttarilla Herran uhrin päällä. Kun pappi on toimittanut hänelle sovituksen tekemästään synnistä, hänelle annetaan anteeksi."',
    },
    5: {
        1: '"Joka tekee syntiä kuultuaan jonkun kiroavan toisen tai on sen todistaja joko silminnäkijänä tai muuten asiasta tietoinen, mutta ei kuitenkaan ilmoita sitä, on syynalainen.',
        2: 'Joka tietämättään koskee johonkin saastaiseen, mihin tahansa, joko saastaisen metsäeläimen raatoon tai saastaisen kotieläimen raatoon tai saastaisen matelijan raatoon, on siten tullut saastaiseksi ja syynalaiseksi.',
        3: 'Tai joka tietämättään koskee ihmisen saastaan, olipa se mitä saastaa tahansa, josta tulee saastaiseksi, mutta salaa sen, joutuu syynalaiseksi.',
        4: 'Tai joka ajattelemattomasti puhuen huulillaan tietämättään vannoo tekevänsä jotakin pahaa tai hyvää – vannoipa mitä hyvänsä, mitä ihminen saattaa ajattelemattomasti vannoa – mutta tultuaan siitä tietoiseksi salaa sen, syyllistyy johonkin näistä.',
        5: 'Joka on syyllinen johonkin näistä, tunnustakoon syntinsä.',
        6: 'Tuokoon sitten syntiuhriksi tekemästään synnistä naaraspuolen lampaista ja vuohista, uuhen tai vuohen. Pappi toimittakoon hänelle sovituksen hänen synnistään.',
        7: 'Mutta jos hän ei voi hankkia sellaista eläintä, tuokoon Herralle hyvitykseksi synnistään kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen syntiuhriksi ja toisen polttouhriksi',
        8: 'ja vieköön ne papille. Tämä uhratkoon ensiksi sen, joka on määrätty syntiuhriksi, vääntäköön siltä niskat poikki, päätä kuitenkaan irrottamatta,',
        9: 'ja pirskottakoon syntiuhrin verta alttarin seinälle, ja jäljelle jäävä veri puserrettakoon alttarin juurelle. Se on syntiuhri.',
        10: 'Toisen kyyhkysen hän valmistakoon säädetyllä tavalla polttouhriksi. Kun pappi on näin toimittanut hänelle sovituksen hänen tekemästään synnistä, annetaan hänelle anteeksi.',
        11: 'Jollei hän voi hankkia kahta metsäkyyhkystä tai kahta kyyhkysenpoikaa, tuokoon uhrilahjanaan tekemänsä synnin sovittamiseksi kymmenennen osan eefa-mittaa ydinjauhoja syntiuhriksi, mutta älköön vuodattako siihen öljyä älköönkä panko sen päälle suitsuketta, sillä se on syntiuhri.',
        12: 'Vieköön sen sitten papille, ja pappi ottakoon niitä kourallisen, alttariuhriosan, ja polttakoon sen alttarilla Herran uhrin päällä. Se on syntiuhri.',
        13: 'Kun pappi näin on toimittanut hänelle sovituksen jostakin sellaisesta hänen tekemästään synnistä, annetaan hänelle anteeksi. Papille tulkoon se, mikä ruokauhristakin."',
        14: 'Sitten Herra puhui Moosekselle sanoen:',
        15: '"Jos joku laiminlyö uskollisuuden ja erehdyksessä rikkoo anastamalla sitä, mikä on Herralle pyhitetty, tuokoon hyvityksenä Herralle vikauhriksi virheettömän pässin lampaista, niin monen hopeasekelin arvoisen, pyhäkkösekelin painon mukaan, kuin sinä arvioit.',
        16: 'Sen, mitä hän on anastanut pyhitetystä itselleen, hän korvatkoon. Lisätköön siihen vielä viidennen osan sen arvosta ja antakoon sen papille. Kun pappi on näin toimittanut hänelle sovituksen uhraamalla pässin vikauhriksi, annetaan hänelle anteeksi.',
        17: 'Jos joku rikkoo jotakin Herran käskyä vastaan ja tekee tietämättään sellaista, mitä ei saa tehdä, ja tulee syynalaiseksi,',
        18: 'tuokoon papille vikauhriksi lampaista arviosi mukaisen, virheettömän pässin. Kun pappi on toimittanut hänelle sovituksen siitä erehdyksestä, jonka hän tietämättään teki, hänelle annetaan anteeksi.',
        19: 'Se on vikauhri, sillä hän oli tullut syylliseksi Herran edessä."',
        20: 'Herra puhui Moosekselle sanoen:',
        21: '"Jos joku tekee synnin olemalla uskoton Herraa kohtaan kieltäessään saaneensa lähimmäiseltään, mitä tämä on hänen haltuunsa antanut tai hänen hoitoonsa uskonut, tai mitä hän itse on lähimmäiseltään väkisin ottanut tai vääryydellä anastanut,',
        22: 'tai jos hän on löytänyt kadotetun esineen ja kieltää sen, tai vannoo väärin missä asiassa tahansa, jossa ihminen helposti rikkoo,',
        23: 'niin jos hän näin on tehnyt syntiä ja tullut syynalaiseksi, antakoon takaisin, mitä hän on väkisin ottanut tai vääryydellä anastanut, tai mitä hänen haltuunsa oli uskottu, tai löytämänsä kadotetun esineen,',
        24: 'kaiken, minkä tähden hän oli väärin vannonut, korvatkoon sen täyteen määrään ja pankoon siihen vielä lisäksi viidennen osan sen arvosta. Sille, jonka oma se on, hän antakoon sen sinä päivänä, jona hän toimittaa vikauhrinsa.',
        25: 'Mutta hyvityksenä Herralle hän tuokoon papille vikauhriksi arviosi mukaisen, virheettömän pässin lampaista.',
        26: 'Kun pappi on näin toimittanut hänelle sovituksen Herran edessä, annetaan hänelle anteeksi kaikki, mitä hän on tehnyt sellaista, josta hän on tullut syynalaiseksi."',
    },
    6: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Käske Aaronia ja hänen poikiaan ja sano: Tämä on laki polttouhrista. Polttouhri olkoon alttarin liedellä koko yön aamuun asti, ja tulta pidettäköön siten vireillä alttarilla.',
        3: 'Pappi pukeutukoon pellavapukuunsa ja pukeutukoon pellavahousuihin peittääkseen häpynsä. Korjatkoon pois tuhkan, joksi tuli on kuluttanut polttouhrin alttarilla, ja pankoon sen alttarin viereen.',
        4: 'Riisukoon sitten vaatteensa ja pukeutukoon toisiin vaatteisiin, ja vieköön tuhkan leirin ulkopuolelle puhtaaseen paikkaan.',
        5: 'Tulta pidettäköön siten vireillä alttarilla älköönkä se koskaan sammuko. Pappi sytyttäköön alttarilla puut joka aamu ja asettakoon sen päälle polttouhrin ja polttakoon sen päällä rauhanuhrin rasvat.',
        6: 'Tuli palakoon aina alttarilla koskaan sammumatta.',
        7: 'Tämä on laki ruokauhrista: Aaronin pojat tuokoot sen Herran eteen, alttarin ääreen.',
        8: 'Pappi erottakoon ruokauhrista kourallisen ydinjauhoja, öljyä ja kaiken suitsukkeen, joka on ruokauhrin päällä, ja polttakoon alttarilla alttariuhriosan suloiseksi tuoksuksi Herralle.',
        9: 'Sen, mikä siitä jää tähteeksi, Aaron syököön poikiensa kanssa. Happamattomana se syötäköön pyhässä paikassa. Ilmestysmajan esipihalla he sen syökööt.',
        10: 'Älköön sitä leivottako hapatettuna. Heidän osakseen minä olen sen uhreistani antanut. Se on korkeasti pyhä, kuten myös syntiuhri ja vikauhri.',
        11: 'Jokainen miehenpuoli Aaronin jälkeläisistä syököön siitä. Tämä olkoon heidän ikuinen osuutensa Herran uhreista sukupolvesta sukupolveen. Jokainen, joka niihin koskee, on pyhäkölle pyhitetty."',
        12: 'Herra puhui Moosekselle sanoen:',
        13: '"Tämä olkoon Aaronin ja hänen poikiensa uhrilahja, joka heidän on tuotava Herralle heidän voitelupäivänään: kymmenesosa eefa-mittaa ydinjauhoja jokapäiväiseksi ruokauhriksi, puolet aamulla ja puolet illalla.',
        14: 'Se valmistettakoon leivinlevyllä öljyyn leivottuna. Tuo se hyvin sotkettuna ja uhraa se palasiksi paloiteltuna ruokauhrina suloiseksi tuoksuksi Herralle.',
        15: 'Se pappi, joka hänen pojistaan on voideltu hänen sijaansa, toimittakoon sen. Se on Herran ikuinen osuus. Poltettakoon se kokonaisuhrina.',
        16: 'Jokainen papin ruokauhri on kokonaisuhri. Älköön sitä syötäkö."',
        17: 'Herra puhui Moosekselle sanoen:',
        18: '"Puhu Aaronille ja hänen pojilleen ja sano: Tämä on laki syntiuhrista. Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös syntiuhri Herran edessä. Se on korkeasti pyhä.',
        19: 'Pappi, joka syntiuhrin uhraa, syököön sen. Syötäköön se pyhässä paikassa ilmestysmajan esipihalla.',
        20: 'Jokainen, joka koskee sen lihaan, on pyhäkölle pyhitetty, ja jos sen verta on roiskunut vaatteille, niin pese pyhässä paikassa se, mihin sitä on roiskunut.',
        21: 'Saviastia, jossa se keitetään, rikottakoon. Jos se on keitetty vaskiastiassa, hangattakoon astia puhtaaksi ja huuhdottakoon vedellä.',
        22: 'Jokainen miehenpuoli papeista saakoon sitä syödä. Se on korkeasti pyhää.',
        23: 'Älköön kuitenkaan syötäkö mitään syntiuhria, jonka verta viedään ilmestysmajaan sovituksen toimittamista varten pyhäkössä, vaan se poltettakoon tulella."',
    },
    7: {
        1: '"Tämä on laki vikauhrista. Se on korkeasti pyhä.',
        2: 'Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös vikauhri, ja sen veri vihmottakoon alttarin joka puolelle.',
        3: 'Sen kaikki rasva uhrattakoon, sekä rasvahäntä että sisälmyksiä peittävä rasva,',
        4: 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa oleva rasva ja maksan takalohko, joka tulee irrottaa munuaisten kohdalta.',
        5: 'Pappi polttakoon ne alttarilla uhrina Herralle. Se on vikauhri.',
        6: 'Jokainen miehenpuoli papeista saakoon sitä syödä. Se syötäköön pyhässä paikassa. Se on korkeasti pyhä.',
        7: 'Se, mitä on säädetty syntiuhrista, koskee vikauhriakin. Laki on molemmista sama. Se olkoon sen papin, joka sillä sovituksen toimittaa.',
        8: 'Pappi, joka toimittaa jonkun puolesta polttouhrin, saakoon uhraamansa polttouhriteuraan nahan.',
        9: 'Jokainen ruokauhri, joka paistetaan uunissa, ja jokainen pannussa tai leivinlevyllä valmistettu, olkoon sen papin, joka uhrin toimittaa.',
        10: 'Mutta jokainen muu ruokauhri, oli siihen sekoitettu öljyä tai olipa se kuiva, olkoon kaikkien Aaronin poikien, yhden niin kuin toisenkin.',
        11: 'Tämä on laki rauhanuhrista, joka tuodaan Herralle:',
        12: 'Jos joku tuo sen kiitokseksi, niin tuokoon rauhanuhriteuraan lisäksi öljyyn leivottuja happamattomia leipäkakkuja, öljyllä voideltuja happamattomia rieskoja ja sekoitettuja ydinjauhoja öljyyn leivottuina leipäkakkuina.',
        13: 'Hapatetusta taikinasta leivottujen leipäkakkujen ohella tuokoon tämän uhrilahjansa rauhanuhrina uhratun rauhanuhriteuraan lisäksi.',
        14: 'Tuokoon siitä yhden kutakin uhrilahjalajia anniksi Herralle. Olkoon se sen papin, joka vihmoo rauhanuhrin veren.',
        15: 'Rauhanuhrina uhratun rauhanuhriteuraan liha syötäköön sinä päivänä, jona se on uhrattu, älköönkä siitä jätettäkö mitään seuraavaan aamuun.',
        16: 'Mutta jos uhrilahjana tuotu teuras on lupausuhri tai vapaaehtoinen uhri, syötäköön se sinä päivänä, jona se on tuotu. Jos kuitenkin siitä jää jotakin tähteeksi, se saadaan syödä seuraavana päivänä.',
        17: 'Mutta mitä uhrilihasta on tähteenä kolmantena päivänä, se poltettakoon tulella.',
        18: 'Jos rauhanuhriteuraan lihaa syödään kolmantena päivänä, se ei ole otollista eikä sitä lueta tuojan hyväksi, vaan se on saastaista. Jokainen, joka sitä syö, joutuu syynalaiseksi.',
        19: 'Sitä lihaa, joka on ollut kosketuksissa saastaiseen, mihin tahansa, älköön syötäkö, vaan se poltettakoon tulessa. Muuten jokainen, joka on puhdas, saakoon syödä rauhanuhriteuraan lihaa.',
        20: 'Mutta jokainen, joka saastaisena ollessaan syö rauhanuhriteuraan lihaa, joka kuuluu Herralle, hävitettäköön kansastaan.',
        21: 'Jos joku koskee johonkin saastaiseen, mihin tahansa, joko ihmisen saastaan tai saastaiseen karjaeläimeen tai mihin inhottavaan saastaan tahansa, ja syö rauhanuhriteuraan lihaa, joka kuuluu Herralle, hänet hävitettäköön kansastaan."',
        22: 'Herra puhui Moosekselle sanoen:',
        23: '"Puhu israelilaisille ja sano: Älkää syökö mitään härän, lampaan tai vuohen rasvaa.',
        24: 'Itsestään kuolleen tai kuoliaaksi raadellun eläimen rasva käytettäköön kaikkinaisiin tarpeisiin, mutta älkää sitä syökö.',
        25: 'Sillä jokainen, joka syö sen eläimen rasvaa, josta tuodaan uhri Herralle, hävitettäköön kansastaan.',
        26: 'Älkää myöskään, missä asuttekin, syökö mitään verta, älkää lintujen älkääkä karjaeläinten.',
        27: 'Jokainen, joka syö verta, minkälaista hyvänsä, hävitettäköön kansastaan."',
        28: 'Herra puhui Moosekselle sanoen:',
        29: '"Puhu israelilaisille ja sano: Joka tuo Herralle rauhanuhrinsa, tuokoon Herralle uhrilahjan tästä rauhanuhristaan.',
        30: 'Tuokoon omin käsin Herran uhrit. Tuokoon rasvan sekä rintalihan, ja toimitettakoon niiden heilutus Herran edessä.',
        31: 'Pappi polttakoon rasvan alttarilla, mutta rintaliha olkoon Aaronin ja hänen poikiensa.',
        32: 'Oikea reisi antakaa papille anniksi rauhanuhriteuraistanne.',
        33: 'Se Aaronin pojista, joka uhraa rauhanuhrin veren ja rasvan, saakoon oikean reiden osakseen.',
        34: 'Sillä minä olen ottanut heilutusrintalihan ja anniksi annetun reiden israelilaisilta heidän rauhanuhriteuraistaan ja antanut ne pappi Aaronille ja hänen pojilleen ikuiseksi osuudeksi israelilaisilta."',
        35: 'Tämä on Aaronin ja hänen poikiensa osa Herran uhreista, joka heille määrättiin sinä päivänä, jona hän toi heidät pappeina palvelemaan Herraa.',
        36: 'Sen osan Herra käski sinä päivänä, jona hän heidät voiteli, israelilaisten antaa heille ikuiseksi osuudeksi sukupolvesta sukupolveen.',
        37: 'Nämä ovat lait polttouhrista, ruokauhrista, syntiuhrista, vikauhrista, vihkiäisuhrista ja rauhanuhrista.',
        38: 'Nämä lait Herra antoi Moosekselle Siinain vuorella sinä päivänä, jona hän antoi israelilaisille käskyn tuoda uhrilahjansa Herralle Siinain erämaassa.',
    },
    8: {
        1: 'Sitten Herra puhui Moosekselle sanoen:',
        2: '"Ota Aaron ja hänen poikansa sekä heidän vaatteensa ja voiteluöljy sekä syntiuhrimulli ja ne kaksi pässiä ja kori, jossa ovat happamattomat leivät.',
        3: 'Kokoa koko seurakunta ilmestysmajan oven edustalle."',
        4: 'Mooses teki, niin kuin Herra oli häntä käskenyt, ja seurakunta kokoontui ilmestysmajan oven edustalle.',
        5: 'Mooses sanoi seurakunnalle: "Näin on Herra käskenyt tehdä."',
        6: 'Mooses toi Aaronin ja hänen poikansa esille ja pesi heidät vedellä.',
        7: 'Sitten hän pani hänen päälleen paidan, vyötti hänet vyöllä, puki hänet viittaan ja pani kasukan hänen päälleen, vyötti hänet kasukan vyöllä ja sitoi sen hänen ympärilleen.',
        8: 'Sitten hän asetti hänen rintaansa rintakilven, pani kilpeen uurimin ja tummimin.',
        9: 'Vielä hän pani turbaanin hänen päähänsä ja kiinnitti turbaanin etupuolelle kultaisen otsakoristeen, pyhän otsalehden, niin kuin Herra oli Moosesta käskenyt.',
        10: 'Sitten Mooses otti voiteluöljyn ja voiteli asumuksen ja kaikki, mitä siinä oli, ja pyhitti ne.',
        11: 'Hän pirskotti sitä seitsemän kertaa alttarille ja voiteli alttarin ja sen koko esineistön sekä altaan jalustoineen pyhittäen ne.',
        12: 'Hän vuodatti voiteluöljyä Aaronin päähän ja voiteli hänet pyhittäen hänet.',
        13: 'Mooses toi esille Aaronin pojat ja puki heidän ylleen paidat ja vyötti heidät vyöllä ja sitoi päähineet heidän päähänsä, niin kuin Herra oli Moosesta käskenyt.',
        14: 'Hän toi syntiuhrimullin, ja Aaron ja hänen poikansa laskivat kätensä syntiuhrimullin pään päälle.',
        15: 'Mooses teurasti mullin, otti sen verta, siveli sitä sormellaan alttarin sarviin ympäriinsä ja puhdisti alttarin. Muun veren hän vuodatti alttarin juurelle ja pyhitti sen toimittamalla sen sovituksen.',
        16: 'Mooses otti kaiken sisälmysten päällä olevan rasvan ja maksan takalohkon ja molemmat munuaiset rasvoineen ja poltti ne alttarilla.',
        17: 'Mutta mullin nahkoineen, lihoineen ja ruokasulineen hän poltti tulessa leirin ulkopuolella, niin kuin Herra oli Moosesta käskenyt.',
        18: 'Hän toi esille polttouhripässin, ja Aaron ja hänen poikansa laskivat kätensä pässin pään päälle.',
        19: 'Mooses teurasti sen ja vihmoi veren alttarille sen joka puolelle',
        20: 'ja leikkeli pässin määräpaloiksi. Sitten Mooses poltti pään sekä palat ja rasvan.',
        21: 'Mutta sisälmykset ja jalat hän pesi vedessä. Sitten Mooses poltti koko pässin alttarilla. Se oli polttouhri suloiseksi tuoksuksi, uhri Herralle, niin kuin Herra oli Moosesta käskenyt.',
        22: 'Sitten hän toi esille toisen pässin, vihkiäispässin, ja Aaron ja hänen poikansa laskivat kätensä pässin pään päälle.',
        23: 'Mooses teurasti sen, otti sen verta ja siveli sitä Aaronin oikeaan korvalehteen, oikean käden peukaloon ja oikean jalan isoonvarpaaseen.',
        24: 'Sitten Mooses toi Aaronin pojat esille ja siveli verta heidän oikeaan korvalehteensä, oikean kätensä peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmoi muun veren alttarin joka puolelle.',
        25: 'Hän otti rasvan ja rasvahännän ja kaiken sisälmysten päällä olevan rasvan ja maksan takalohkon ja molemmat munuaiset rasvoineen ja oikean reiden.',
        26: 'Hän otti happamattomien leipien korista, joka oli Herran edessä, yhden happamattoman leipäkakun, yhden öljyyn leivotun leipäkakun ja yhden rieskan ja pani ne rasvojen ja oikean reiden päälle.',
        27: 'Hän pani kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, ja toimitutti niiden heilutuksen Herran edessä.',
        28: 'Mooses otti ne heidän käsistään ja poltti ne alttarilla polttouhrin päällä. Tämä oli vihkiäisuhri suloiseksi tuoksuksi, uhri Herralle.',
        29: 'Sitten Mooses otti rintalihan ja toimitti sen heilutuksen Herran edessä. Vihkiäispässistä tämä tuli Mooseksen osalle, niin kuin Herra oli Moosesta käskenyt.',
        30: 'Mooses otti voiteluöljyä ja verta, jota oli alttarilla, pirskotti sitä Aaronin ja hänen vaatteittensa päälle ja samoin hänen poikiensa ja heidän vaatteittensa päälle ja pyhitti niin Aaronin ja hänen vaatteensa sekä hänen poikansa ja heidän vaatteensa.',
        31: 'Mooses sanoi Aaronille ja hänen pojilleen: "Keittäkää liha ilmestysmajan ovella ja syökää se siinä sekä leipä, joka on vihkiäisuhriin kuuluvassa korissa, niin kuin minä olen käskenyt ja sanonut: Aaron poikineen syököön sen.',
        32: 'Mutta mitä jää tähteeksi lihasta ja leivästä, polttakaa tulella.',
        33: 'Seitsemään päivään älkää lähtekö ilmestysmajan ovelta, älkää ennen kuin vihkimispäivänne ovat kuluneet umpeen, sillä seitsemän päivää kestää vihkimisenne.',
        34: 'Niin kuin on tehty tänä päivänä, niin Herra on käskenyt vastakin tehdä toimittaakseen teille sovituksen.',
        35: 'Olkaa seitsemän päivää ilmestysmajan oven edustalla, päivät ja yöt, ja toimittakaa Herran palvelustehtävät, ettette kuolisi. Sillä niin on minulle käsky annettu."',
        36: 'Aaron ja hänen poikansa tekivät kaiken, mitä Herra oli Mooseksen kautta käskenyt.',
    },
    9: {
        1: 'Kahdeksantena päivänä Mooses kutsui Aaronin, hänen poikansa ja Israelin vanhimmat',
        2: 'ja sanoi Aaronille: "Ota itsellesi härkävasikka syntiuhriksi ja pässi polttouhriksi, molemmat virheettömiä, ja tuo ne Herran eteen.',
        3: "Puhu israelilaisille ja sano: 'Ottakaa vuohipukki syntiuhriksi ja vasikka ja karitsa, molemmat vuoden vanhoja ja virheettömiä, polttouhriksi.",
        4: '[Ottakaa] myös härkä ja pässi rauhanuhriksi, uhrattaviksi Herran edessä, sekä ruokauhri, johon on sekoitettu öljyä, sillä tänä päivänä ilmestyy teille Herra.\'"',
        5: 'Niin he toivat, mitä Mooses oli käskenyt, ilmestysmajan edustalle, ja koko seurakunta astui esiin ja asettui Herran eteen.',
        6: 'Mooses sanoi: "Näin Herra on käskenyt teidän tehdä, jotta Herran kirkkaus ilmestyisi teille."',
        7: 'Mooses sanoi Aaronille: "Astu alttarin luo, uhraa syntiuhrisi ja polttouhrisi ja toimita itsellesi ja kansalle sovitus sekä uhraa sitten kansan uhrilahja ja toimita heille sovitus, niin kuin Herra on käskenyt."',
        8: 'Aaron astui alttarin luo ja teurasti oman syntiuhrivasikkansa.',
        9: 'Aaronin pojat ojensivat hänelle veren. Hän kastoi sormensa vereen ja siveli sitä alttarin sarviin, mutta muun veren hän vuodatti alttarin juurelle.',
        10: 'Mutta syntiuhriteuraan rasvan ja munuaiset ja maksan takalohkon hän poltti alttarilla, niin kuin Herra oli Moosesta käskenyt.',
        11: 'Lihan ja nahan hän poltti tulella leirin ulkopuolella.',
        12: 'Hän teurasti polttouhrin, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarin joka taholle.',
        13: 'He ojensivat hänelle polttouhrin paloina sekä pään, ja hän poltti ne alttarilla.',
        14: 'Hän pesi sisälmykset ja jalat ja poltti ne polttouhrin päällä alttarilla.',
        15: 'Sitten hän toi kansan uhrilahjan ja otti kansan syntiuhrivuohen, teurasti sen ja uhrasi sen syntiuhrina samalla tavalla kuin edellisen.',
        16: 'Hän toi myös polttouhrin ja uhrasi sen säädetyllä tavalla.',
        17: 'Hän toi ruokauhrin ja otti siitä täyden kourallisen ja poltti sen alttarilla aamupolttouhrin lisäksi.',
        18: 'Hän teurasti härän ja pässin kansan rauhanuhriksi, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarin joka puolelle.',
        19: 'Mutta härän ja pässin rasvat, rasvahännän, rasvakalvon, munuaiset ja maksan takalohkon,',
        20: 'nämä rasvat he panivat rintalihojen päälle, ja hän poltti rasvat alttarilla.',
        21: 'Rintalihan ja oikean reiden heilutuksen Aaron toimitti Herran edessä, niin kuin Mooses oli käskenyt.',
        22: 'Aaron kohotti kätensä kansaa kohti ja siunasi heidät. Kun hän oli toimittanut syntiuhrin, polttouhrin ja rauhanuhrin, hän astui alas.',
        23: 'Mooses ja Aaron menivät ilmestysmajaan. Kun he tulivat sieltä ulos, he siunasivat kansan. Silloin Herran kirkkaus ilmestyi kaikelle kansalle.',
        24: 'Tuli lähti Herran luota ja kulutti polttouhrin ja rasvat alttarilta. Kaikki kansa näki sen, ja he riemuitsivat ja lankesivat kasvoilleen.',
    },
    10: {
        1: 'Aaronin pojat Naadab ja Abihu ottivat kumpikin hiilipannunsa ja virittivät niihin tulen ja panivat suitsuketta sen päälle ja toivat vierasta tulta Herran eteen vastoin hänen käskyään.',
        2: 'Silloin tuli lähti Herran luota ja kulutti heidät, niin että he kuolivat Herran edessä.',
        3: 'Mooses sanoi Aaronille: "Tämä tapahtuu Herran sanan mukaan: Niissä, jotka ovat minua lähellä, minä osoitan pyhyyteni ja kaiken kansan edessä kirkkauteni." – Mutta Aaron oli ääneti.',
        4: 'Mooses kutsui Miisaelin ja Elsafanin, Aaronin sedän Ussielin pojat, ja sanoi heille: "Astukaa esiin ja kantakaa sukulaisenne pyhäkön läheisyydestä leirin ulkopuolelle."',
        5: 'He astuivat esiin ja kantoivat heidät viittoineen leirin ulkopuolelle, niin kuin Mooses oli sanonut.',
        6: 'Mooses sanoi Aaronille ja hänen pojilleen Eleasarille ja Iitamarille: "Älkää päästäkö tukkaanne hajalle älkääkä repikö vaatteitanne, ettette kuolisi ja ettei hänen vihansa kohtaisi koko seurakuntaa. Mutta teidän veljenne, koko Israelin heimo, itkekööt tätä paloa, jonka Herra on sytyttänyt.',
        7: 'Älkää poistuko ilmestysmajan ovelta, ettette kuolisi, sillä Herran voiteluöljy on teissä." He tekivät, niin kuin Mooses oli sanonut.',
        8: 'Herra puhui Aaronille sanoen:',
        9: '"Viiniä ja väkijuomaa älkää juoko, älä sinä älköötkä poikasi kanssasi, kun menette ilmestysmajaan, ettette kuolisi. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen,',
        10: 'tehdäksenne erotuksen pyhän ja epäpyhän, saastaisen ja puhtaan välillä,',
        11: 'ja opettaaksenne israelilaisille kaikki ne käskyt, jotka Herra on heille puhunut Mooseksen kautta."',
        12: 'Mooses puhui Aaronille ja hänen eloon jääneille pojilleen Eleasarille ja Iitamarille: "Ottakaa Herran uhreista tähteeksi jäänyt ruokauhri ja syökää se happamattomana alttarin ääressä, sillä se on korkeasti pyhä.',
        13: 'Syökää se pyhässä paikassa, sillä se on sinun osuutesi ja poikiesi osuus Herran uhreista. Niin on minulle käsky annettu.',
        14: 'Heilutusrintaliha ja anniksi annettu reisi syökää puhtaassa paikassa, sinä ja poikasi ja tyttäresi kanssasi. Sillä ne ovat sinun osuudeksesi ja sinun poikiesi osuudeksi annetut israelilaisten rauhanuhriteuraista.',
        15: 'Anniksi annettu reisi ja heilutusrintaliha tuotakoon uhrirasvojen kanssa ja toimitettakoon niiden heilutus Herran edessä. Ne olkoot sinun ja poikiesi ikuinen osuus, niin kuin Herra on käskenyt."',
        16: 'Mooses tiedusteli syntiuhripukkia, ja katso, se oli poltettu. Silloin hän vihastui Eleasariin ja Iitamariin, Aaronin eloon jääneille pojille, ja sanoi:',
        17: '"Miksi ette ole syöneet syntiuhria pyhässä paikassa? Sehän on korkeasti pyhä. Hän on antanut sen teille, että poistaisitte kansan syntivelan ja toimittaisitte heille sovituksen Herran edessä.',
        18: 'Katso, sen verta ei ole tuotu pyhäkköön sisälle. Teidän olisi tullut syödä se pyhäkössä, niin kuin olen käskenyt."',
        19: 'Mutta Aaron sanoi Moosekselle: "Katso, he ovat tänä päivänä tuoneet syntiuhrinsa ja polttouhrinsa Herran eteen, ja kuitenkin on tämä minua kohdannut. Jos minä tänä päivänä söisin syntiuhria, olisikohan se Herralle otollista?"',
        20: 'Sen kuultuaan Mooses hyväksyi sen.',
    },
    11: {
        1: 'Herra puhui Moosekselle ja Aaronille sanoen heille:',
        2: '"Puhukaa israelilaisille ja sanokaa: Näitä eläimiä saatte syödä kaikista nelijalkaisista eläimistä maan päällä:',
        3: 'Kaikkia nelijalkaisia eläimiä, joilla on kokonaan halkinaiset sorkat ja jotka märehtivät, saatte syödä.',
        4: 'Näitä älkää kuitenkaan syökö niistä, jotka märehtivät, ja niistä, joilla on sorkat: Kameli, joka kyllä märehtii, mutta jolla ei ole sorkkia, olkoon teille saastainen.',
        5: 'Tamaani, joka tosin märehtii, mutta jolla ei ole sorkkia, olkoon teille saastainen.',
        6: 'Jänis, joka kyllä märehtii, mutta jolla ei ole sorkkia, olkoon teille saastainen.',
        7: 'Sika, jolla tosin on kokonaan halkinaiset sorkat, mutta joka ei märehdi, olkoon teille saastainen.',
        8: 'Näiden lihaa älkää syökö ja näiden raatoihin älkää koskeko. Ne olkoot teille saastaisia.',
        9: 'Näitä saatte syödä kaikista vesieläimistä: te saatte syödä kaikkia, joilla on evät ja suomukset ja jotka elävät vedessä, niin hyvin merissä kuin joissa.',
        10: 'Mutta inhotkaa kaikkia niitä, joita vedet vilisevät, kaikkia veden eläviä, mutta joilla ei ole eviä eikä suomuksia, elivätpä merissä tai joissa.',
        11: 'Niitä inhotkaa. Älkää syökö niiden lihaa. Inhotkaa myös niiden raatoja.',
        12: 'Kaikkia niitä vesieläimiä, joilla ei ole eviä eikä suomuksia, inhotkaa.',
        13: 'Linnuista taas inhotkaa seuraavia älkääkä niitä syökö, vaan olkoot ne teille iljettäviä: kotka, partakorppikotka ja hanhikorppikotka,',
        14: 'haarahaukka ja muut haukat,',
        15: 'kaikki korpit,',
        16: 'strutsi, pääskynen, lokki ja jalohaukkalajit,',
        17: 'huuhkaja, kalasääski ja kissapöllö,',
        18: 'sarvipöllö, pelikaani ja likakorppikotka,',
        19: 'haikara ja sirriäislajit, harjalintu ja lepakko.',
        20: 'Kaikkia siivellisiä pikkueläimiä, jotka liikkuvat neljällä jalalla, inhotkaa.',
        21: 'Kuitenkin saatte siivellisistä pikkueläimistä, jotka liikkuvat neljällä jalalla, syödä niitä, joilla jalkaterien yläpuolella on kaksi säärtä hypelläkseen niillä maassa.',
        22: 'Niistä saatte syödä seuraavia: heinäsirkkalajeja, solam-sirkkalajeja, hargol-sirkkalajeja ja haagab-sirkkalajeja.',
        23: 'Mutta kaikkia muita siivellisiä pikkueläimiä, joilla on neljä jalkaa, inhotkaa.',
        24: 'Seuraavista eläimistä te tulette saastaisiksi. Jokainen, joka koskee niiden raatoihin, olkoon iltaan asti saastainen.',
        25: 'Jokainen, joka kantaa niiden raatoja, pesköön vaatteensa ja olkoon saastainen iltaan asti.',
        26: 'Kaikki nelijalkaiset eläimet, joilla on sorkat, mutta ei kokonaan halkinaiset, ja jotka eivät märehdi, olkoot teille saastaiset. Jokainen, joka koskee niihin, olkoon saastainen.',
        27: 'Kaikki nelijalkaiset eläimet, jotka kulkevat käpälillä, olkoot teille saastaisia. Jokainen, joka koskettaa niiden raatoja, olkoon iltaan asti saastainen.',
        28: 'Joka kantaa niiden raatoja, pesköön vaatteensa ja olkoon saastainen iltaan asti. Ne olkoot teille saastaiset.',
        29: 'Myös nämä olkoot teille saastaisia niistä pikkueläimistä, jotka liikkuvat maassa: myyrä, hiiri ja sisiliskolajit,',
        30: 'anaka-eläin, kooah-eläin, leeta-eläin, hoomet-eläin ja kameleontti.',
        31: 'Ne olkoot teille saastaisia kaikista pikkueläimistä. Jokainen, joka niihin koskee, kun ne ovat kuolleet, olkoon saastainen iltaan asti.',
        32: 'Kaikki, minkä päälle jokin niistä kuolleena putoaa, on saastaista, olipa se sitten puuastia tai vaatekappale tai nahka tai säkki tai mikä tahansa tarvekalu. Se pantakoon veteen ja olkoon saastainen iltaan asti. Sitten se on puhdas.',
        33: 'Jos jokin niistä putoaa saviastiaan, kaikki, mitä siinä on, on saastaista, ja astia rikottakoon.',
        34: 'Kaikki ruoka, jota syödään, on saastaista, jos sen astian vettä tulee siihen, ja kaikki juoma, jota juodaan, on jokaisessa sellaisessa astiassa saastaista.',
        35: 'Kaikki, minkä päälle niiden raato putoaa, tulee saastaiseksi. Olkoonpa se leivinuuni tai liesi, revittäköön se maahan. Sillä saastaisia ne ovat ja saastaisia ne olkoot teille.',
        36: 'Kuitenkin lähde tai kaivo, paikka, johon vettä on kokoontunut, pysyy puhtaana. Mutta joka niiden raatoon koskee, olkoon saastainen.',
        37: 'Jos niiden raato putoaa kylvösiemenen päälle, minkä hyvänsä, joka kylvetään, pysyy tämä puhtaana.',
        38: 'Mutta jos siemen on vedellä kasteltu ja niiden raato putoaa sen päälle, tulee siemen teille saastaiseksi.',
        39: 'Jos jokin eläin, joka on teille ravinnoksi, kuolee, olkoon se, joka sen raatoon koskee, saastainen iltaan asti.',
        40: 'Joka syö sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti. Se, joka kantaa sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti.',
        41: 'Kaikki pikkueläimet, jotka liikkuvat maassa, olkoot inhottavia. Älköön niitä syötäkö.',
        42: 'Kaikista niistä, jotka kulkevat vatsallaan, ja kaikista pikkueläimistä, jotka liikkuvat maassa, kulkien neljällä tai useammalla jalalla, älkää syökö niistä mitään, sillä ne ovat inhottavia.',
        43: 'Älkää saattako itseänne inhottaviksi koskettamalla matelevaa pikkueläintä, mitä tahansa, älkääkä saastuttako itseänne niillä, niin että tulette niistä saastaisiksi.',
        44: 'Sillä minä olen Herra, teidän Jumalanne. Pyhittäkää siis itsenne ja olkaa pyhät, sillä minä olen pyhä. Älkää saastuttako itseänne koskemalla mihinkään pikkueläimeen, joka liikkuu maassa.',
        45: 'Sillä minä olen Herra, joka olen johdattanut teidät Egyptin maasta, ja joka olen teidän Jumalanne. Olkaa siis pyhät, sillä minä olen pyhä.',
        46: 'Tämä on laki nelijalkaisista eläimistä ja linnuista ja kaikista elollisista, joita vilisee vedessä, ja kaikista olennoista, joita liikkuu maassa,',
        47: 'että tietäisitte erottaa puhtaat saastaisista ja syötävät eläimet niistä eläimistä, joita ei saa syödä."',
    },
    12: {
        1: 'Sitten Herra puhui Moosekselle sanoen:',
        2: '"Puhu israelilaisille ja sano: Kun vaimo tulee hedelmälliseksi ja synnyttää pojan, olkoon saastainen seitsemän päivää. Hän olkoon saastainen yhtä monta päivää kuin hänen kuukautisensa kestävät.',
        3: 'Kahdeksantena päivänä ympärileikattakoon pojan esinahan liha.',
        4: 'Mutta vaimo pysyköön kotona kolmekymmentä kolme päivää puhdistavan verenvuotonsa aikana. Älköön koskeko mihinkään, mikä on pyhää. Älköön myöskään tulko pyhäkköön, ennen kuin hänen puhdistuspäivänsä ovat kuluneet umpeen.',
        5: 'Mutta jos hän synnyttää tytön, olkoon saastainen kaksi viikkoa samoin kuin kuukautisissaan, ja pysyköön kotona kuusikymmentä kuusi päivää puhdistavan verenvuotonsa aikana.',
        6: 'Mutta kun hänen puhdistuspäivänsä pojan tai tyttären jälkeen ovat kuluneet umpeen, vieköön vuoden vanhan karitsan polttouhriksi ja kyyhkysenpojan tai metsäkyyhkysen syntiuhriksi ilmestysmajan oven edustalle papille.',
        7: 'Tämä tuokoon ne Herran eteen ja toimittakoon hänelle sovituksen, niin hän on puhdas verenvuodostaan. Tämä on laki lapsensynnyttäjästä, olipa hän synnyttänyt pojan tai tytön.',
        8: 'Mutta jos hän ei saa hankituksi lammasta, ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen polttouhriksi ja toisen syntiuhriksi. Sitten pappi toimittakoon hänelle sovituksen, niin hän on puhdas."',
    },
    13: {
        1: 'Herra puhui Moosekselle ja Aaronille sanoen:',
        2: '"Jos jonkun ihoon tulee nystyrä tai ihottuma tai vaalea pilkku, niin kuin spitaalilaikku olisi tulossa hänen ihoonsa, vietäköön hänet pappi Aaronin tai jonkun hänen poikansa, pappien, eteen.',
        3: 'Jos pappi tutkiessaan laikkua iholla huomaa, että karvat laikussa ovat muuttuneet valkoisiksi ja että laikku näyttää muuta ihoa matalammalta, se on spitaalilaikku. Heti kun pappi on sen huomannut, julistakoon hänet saastaiseksi.',
        4: 'Jos taas hänen ihollaan on valkea pilkku, mutta se ei näytä muuta ihoa matalammalta eivätkä karvat ole muuttuneet valkoisiksi, sulkekoon pappi laikkuisen sisälle seitsemäksi päiväksi.',
        5: 'Seitsemäntenä päivänä pappi tarkastakoon hänet. Jos laikku hänestä näyttää pysyneen entisellään vaivan leviämättä ihossa, sulkekoon pappi hänet sisälle vielä seitsemäksi päiväksi.',
        6: 'Seitsemäntenä päivänä pappi tutkikoon hänet uudestaan. Jos hän huomaa, että laikku on käynyt vaaleaksi ja että laikku ei ole ihossa levinnyt, julistakoon pappi hänet puhtaaksi, sillä se on ihottumaa. Pesköön vaatteensa, ja niin hän on puhdas.',
        7: 'Mutta jos ihottuma leviää leviämistään hänen ihollaan, sen jälkeen kun hän oli näyttäytynyt papille tullakseen puhtaaksi julistetuksi, näyttäytyköön uudestaan papille.',
        8: 'Jos pappi huomaa ihottuman levinneen iholla, julistakoon pappi hänet saastaiseksi. Se on spitaalia.',
        9: 'Jos spitaalilaikku ilmestyy ihmiseen, vietäköön hänet papin luo.',
        10: 'Jos pappi tutkiessaan huomaa iholla valkoisen nystyrän, jonka kohdalta karvat ovat muuttuneet valkoisiksi, ja liikaa lihaa kasvavan nystyrän,',
        11: 'on hänen ihollaan jo vanha spitaali, ja sen tähden pappi julistakoon hänet saastaiseksi älköönkä enää sulkeko häntä sisälle, sillä hän on saastainen.',
        12: 'Jos taas spitaali puhkeaa iholla, niin että se peittää koko ihon päästä jalkoihin asti, minne pappi katsookin,',
        13: 'ja jos pappi tutkiessaan huomaa spitaalin peittävän koko ihon, julistakoon hänet puhtaaksi. Hän on kokonaan muuttunut valkoiseksi ja on puhdas.',
        14: 'Mutta niin pian kuin häneen ilmestyy verestävää lihaa, hän on saastainen.',
        15: 'Kun pappi huomaa verestävän lihan, julistakoon hänet saastaiseksi. Verestävä liha on saastaista. Se on spitaalia.',
        16: 'Mutta jos verestävä liha häviää ja paikka muuttuu valkoiseksi, menköön papin luo.',
        17: 'Jos pappi huomaa, että paikka on muuttunut valkoiseksi, julistakoon hänet puhtaaksi. Hän on puhdas.',
        18: 'Jos jonkun ihoon tulee paise, joka paranee,',
        19: 'ja paiseen tilalle tulee valkoinen nystyrä tai vaaleanpunainen pilkku, näyttäytyköön papille.',
        20: 'Jos pappi tutkiessaan huomaa, että paikka näyttää muuta ihoa matalammalta ja että karvat siinä ovat muuttuneet valkoisiksi, julistakoon hänet saastaiseksi. Paiseeseen on puhjennut spitaali.',
        21: 'Mutta jos pappi tutkiessaan huomaa, ettei siinä ole valkoisia karvoja ja ettei paikka ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, sulkekoon hänet sisälle seitsemäksi päiväksi.',
        22: 'Jos se leviää leviämistään hänen ihollaan, julistakoon pappi hänet saastaiseksi. Se on spitaalia.',
        23: 'Mutta jos laikku pysyy ennallaan laajenematta, se on paiseen arpi. Pappi julistakoon hänet puhtaaksi.',
        24: 'Jos taas joku saa palohaavan ihoonsa ja palohaavaan kasvavaan lihaan ilmestyy vaaleanpunainen tai valkoinen pilkku,',
        25: 'ja jos pappi tutkiessaan huomaa laikun karvojen muuttuneen valkoisiksi ja paikan näyttävän muuta ihoa matalammalta, niin palohaavaan on puhjennut spitaali. Pappi julistakoon hänet saastaiseksi. Se on spitaalia.',
        26: 'Mutta jos pappi tutkiessaan huomaa, ettei pilkussa ole valkoisia karvoja eikä se ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, sulkekoon hänet sisälle seitsemäksi päiväksi.',
        27: 'Seitsemäntenä päivänä pappi tutkikoon hänet. Jos se on yhä levinnyt iholla, julistakoon hänet saastaiseksi. Se on spitaalia.',
        28: 'Mutta jos pilkku on pysynyt alallaan eikä ole levinnyt iholla ja on edelleen vaalennut, se on palohaavasta syntynyt nystyrä. Pappi julistakoon hänet puhtaaksi. Se on palohaavan arpi.',
        29: 'Jos mieheen tai naiseen tulee läikkä päähän tai partaan,',
        30: 'ja jos pappi tutkiessaan läikkää huomaa, että se näyttää muuta ihoa matalammalta ja että siinä on ohuita, kellertäviä karvoja, julistakoon hänet saastaiseksi. Se on spitaalisyyhyä. Se on pää- tai partaspitaalia.',
        31: 'Jos pappi tutkiessaan paikkaa huomaa, ettei se näytä muuta ihoa matalammalta, mutta ettei siinä ole mustia karvoja, sulkekoon syyhyisen sisälle seitsemäksi päiväksi.',
        32: 'Jos pappi seitsemäntenä päivänä tutkiessaan läikkää huomaa, ettei syyhy ole levinnyt ja ettei siinä ole kellertäviä karvoja ja ettei syyhy näytä muuta ihoa matalammalta,',
        33: 'tutkittava ajakoon hiuksensa tai partansa, kuitenkaan ajamatta läikkää, ja pappi sulkekoon syyhyisen sisälle vielä seitsemäksi päiväksi.',
        34: 'Jos pappi seitsemäntenä päivänä tutkiessaan läikkää huomaa, ettei syyhy ole levinnyt iholla ja ettei se näytä muuta ihoa matalammalta, julistakoon hänet puhtaaksi. Hän pesköön vaatteensa, ja niin hän on puhdas.',
        35: 'Mutta jos syyhy leviää leviämistään iholla, sen jälkeen kun hänet julistettiin puhtaaksi,',
        36: 'ja jos pappi tutkiessaan häntä huomaa, että syyhy on levinnyt iholla, älköön pappi enää etsikö kellertäviä karvoja. Hän on saastainen.',
        37: 'Mutta jos syyhy näyttää hänestä pysyneen entisellään ja jos siihen on kasvanut mustia karvoja, syyhy on parantunut. Hän on puhdas. Pappi julistakoon hänet puhtaaksi.',
        38: 'Jos miehen tai naisen ihoon tulee pilkkuja, jotka ovat valkoisia,',
        39: 'ja jos pappi tutkiessaan huomaa vaalenevia, valkoisia pilkkuja heidän ihollaan, se on vaaratonta valkoista ihottumaa, joka on puhjennut ihoon. Hän on puhdas.',
        40: 'Jos hiukset lähtevät miehen päästä takaraivolta, hän on takakalju. Hän on puhdas.',
        41: 'Jos taas hiukset lähtevät päästä ohimoista, hän on otsakalju. Hän on puhdas.',
        42: 'Mutta jos vaaleanpunainen laikku ilmestyy takaraivon tai otsapuolen paljaaseen paikkaan, se on spitaalia, joka on puhkeamassa takaraivon tai otsapuolen paljaaseen kohtaan.',
        43: 'Jos pappi tutkiessaan häntä huomaa, että nystyrä takaraivon tai otsapuolen paljaassa kohdassa on vaaleanpunainen näyttäen samanlaiselta kuin spitaali muussa ihossa,',
        44: 'mies on spitaalinen ja saastainen. Pappi julistakoon hänet heti saastaiseksi hänen päässään olevan läikän tähden.',
        45: "Jolla on spitaali, käyköön rikkirevityissä vaatteissa, tukka hajalla ja parta peitettynä ja huutakoon: 'Saastainen, saastainen!'",
        46: 'Niin kauan kuin ihomuutos hänessä on, hän olkoon saastainen. Koska hän on saastainen, asukoon yksinään. Hänen asuinpaikkansa olkoon leirin ulkopuolella.',
        47: 'Jos spitaalilaikku tulee vaatteeseen, olipa vaate villainen tai pellavainen,',
        48: 'tai kudottuun tai solmustettuun kankaaseen, olipa se pellavaa tai villaa, tai nahkaa tai mikä tahansa nahasta tehty esine,',
        49: 'ja jos laikku näyttää vihertävältä tai punertavalta vaatekappaleessa, nahassa, kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa, se on spitaalia. Se on näytettävä papille.',
        50: 'Kun pappi on tutkinut laikun, sulkekoon esineen sisälle seitsemäksi päiväksi.',
        51: 'Jos hän seitsemäntenä päivänä tutkiessaan laikun huomaa, että laikku on levinnyt vaatteessa tai kudotussa tai solmustetussa kankaassa tai nahassa tai mihin nahasta tehdyssä esineessä tahansa, laikku on pahanlaatuista spitaalia. Ne ovat saastaisia.',
        52: 'Polttakoon vaatteen tai kudotun tai solmustetun kankaan, olipa se villaa, pellavaa tai nahasta tehty esine, tai olipa se mikä tahansa, jossa laikku on, sillä se on pahanlaatuista spitaalia. Kaikki sellainen poltettakoon tulessa.',
        53: 'Mutta jos pappi tarkastaessaan huomaa, ettei laikku ole levinnyt vaatekappaleessa, kudotussa tai solmustetussa kankaassa tai nahasta tehdyssä esineessä, olipa se mikä tahansa,',
        54: 'käskeköön pestä esineen, jossa laikku on, ja sulkekoon sen sisälle vielä seitsemäksi päiväksi.',
        55: 'Jos pappi tarkastaessaan esinettä, sen jälkeen kun se on pesty, huomaa, ettei laikku ole muuttunut näöltään, esine, vaikka laikku ei olekaan levinnyt, on saastainen. Se poltettakoon tulessa. Se on spitaalin syömä, olkoon sitten nurjalta tai oikealta puolelta.',
        56: 'Mutta jos pappi tutkiessaan huomaa, että laikku on pesemisen jälkeen vaalennut, reväisköön sen pois vaatekappaleesta, nahasta tai kudotusta tai solmustetusta kankaasta.',
        57: 'Jos sitten vielä laikku ilmestyy vaatekappaleeseen, kudottuun tai solmustettuun kankaaseen tai mihin nahasta tehtyyn esineeseen tahansa, se on puhkeavaa spitaalia. Esine, jossa laikku on, poltettakoon tulessa.',
        58: 'Mutta vaatekappale, kudottu tai solmustettu kangas tai mikä nahasta tehty esine tahansa, josta laikku on pesemällä kadonnut, pestäköön vielä kerran, ja niin se on puhdas."',
        59: 'Tämä on laki spitaalilaikusta vaatteessa, villaisessa tai pellavaisessa, kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa. Tämä on laki niiden puhtaiksi tai saastaisiksi julistamisesta.',
    },
    14: {
        1: 'Sitten Herra puhui Moosekselle sanoen:',
        2: '"Tämä olkoon laki spitaalisen puhdistamispäivästä. Hänet tuotakoon papin luo,',
        3: 'ja pappi menköön leirin ulkopuolelle. Jos pappi tarkastaessaan spitaalista huomaa, että hän on parantunut spitaaliläikästä,',
        4: 'käskeköön pappi puhdistettavaa varten ottamaan kaksi elävää, puhdasta lintua, setripuuta, helakanpunaista lankaa ja iisoppikorren.',
        5: 'Pappi käskeköön teurastamaan toisen linnun saviastian päällä, jossa on raikasta vettä.',
        6: 'Sitten hän ottakoon elävän linnun ja setripuun, helakanpunaisen langan ja iisoppikorren ja kastakoon ne sekä elävän linnun sen linnun vereen, joka teurastettiin raikkaan veden päällä,',
        7: 'ja pirskottakoon sitä seitsemän kertaa siihen, joka on spitaalista puhdistettava. Puhdistettuaan hänet päästäköön elävän linnun lentämään kedolle.',
        8: 'Puhdistettava pesköön vaatteensa, ajakoon kaikki hiuksensa ja peseytyköön vedessä, niin hän on puhdas. Sen jälkeen hän saa mennä leiriin. Asukoon kuitenkin telttansa ulkopuolella seitsemän päivää.',
        9: 'Ajakoon seitsemäntenä päivänä kaikki hiukset päästään, partansa ja kulmakarvansa. Ajakoon kaikki karvansa. Pesköön sitten vaatteensa ja ruumiinsa vedessä, niin hän on puhdas.',
        10: 'Kahdeksantena päivänä ottakoon kaksi virheetöntä karitsaa ja virheettömän, vuoden vanhan uuhikaritsan sekä ruokauhriksi kolme kymmenennestä ydinjauhoja, joihin on sekoitettu öljyä, ja yhden loog-mitan öljyä.',
        11: 'Puhdistusta toimittava pappi asettakoon puhdistettavan henkilön ja nämä esineet Herran eteen ilmestysmajan ovelle.',
        12: 'Sitten pappi ottakoon toisen karitsan ja tuokoon sen vikauhriksi sekä loog-mitan öljyä, ja toimittakoon niiden heilutuksen Herran edessä.',
        13: 'Teurastakoon sitten karitsan siinä paikassa, jossa syntiuhri- ja polttouhriteuraat teurastetaan, pyhässä paikassa, sillä vikauhri on kuten syntiuhrikin papin. Se on korkeasti pyhä.',
        14: 'Pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.',
        15: 'Sen jälkeen pappi ottakoon öljyä loog-mitasta ja kaatakoon sitä vasempaan käteensä',
        16: 'ja kastakoon oikean kätensä etusormen öljyyn, jota on hänen vasemmassa kädessään, ja pirskottakoon öljyä sormellaan seitsemän kertaa Herran edessä.',
        17: 'Käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen vikauhrin veren päälle.',
        18: 'Käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän. Näin pappi toimittakoon hänelle sovituksen Herran edessä.',
        19: 'Sitten pappi uhratkoon syntiuhrin ja toimittakoon puhdistettavalle sovituksen hänen saastaisuudestaan ja sen jälkeen teurastakoon polttouhriteuraan.',
        20: 'Pappi uhratkoon polttouhrin ja ruokauhrin alttarilla. Kun pappi on toimittanut hänelle sovituksen, hän on puhdas.',
        21: 'Mutta jos hän on köyhä eikä saa hankituksi niin paljoa, ottakoon vain yhden karitsan vikauhriksi heilutettavaksi toimittaakseen itselleen sovituksen, sekä ruokauhriksi vain yhden kymmenenneksen ydinjauhoja, joihin on sekoitettu öljyä ja loog-mitan öljyä,',
        22: 'sekä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, mikäli hän on voinut ne hankkia. Toinen olkoon syntiuhriksi ja toinen polttouhriksi.',
        23: 'Vieköön ne papille puhdistustaan varten kahdeksantena päivänä ilmestysmajan ovelle Herran eteen.',
        24: 'Pappi ottakoon vikauhrikaritsan ja loog-mitan öljyä ja toimittakoon niiden heilutuksen Herran edessä.',
        25: 'Vikauhrikaritsa teurastettakoon, ja pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.',
        26: 'Sitten pappi kaatakoon öljyä vasempaan käteensä,',
        27: 'ja pappi pirskottakoon oikealla etusormellaan öljyä, jota on hänen vasemmassa kädessään, seitsemän kertaa Herran edessä.',
        28: 'Käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen, siihen paikkaan, missä on vikauhrin verta.',
        29: 'Käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän toimittaakseen hänelle sovituksen Herran edessä.',
        30: 'Hän uhratkoon toisen niistä metsäkyyhkysistä tai kyyhkysenpojista, jotka hän on hankkinut,',
        31: 'mikäli on voinut ne hankkia, toisen syntiuhriksi ja toisen polttouhriksi ruokauhrin ohella. Pappi toimittakoon puhdistettavalle sovituksen Herran edessä."',
        32: 'Tämä on laki spitaalisesta, joka ei pysty hankkimaan puhdistukseen sitä, mikä on säädetty.',
        33: 'Sitten Herra puhui Moosekselle ja Aaronille sanoen:',
        34: '"Kun tulette Kanaanin maahan, jonka minä annan teille perintömaaksi, ja minä sallin spitaalin tulla johonkin taloon siinä maassa, jonka saatte perintömaaksenne,',
        35: "talon omistaja menköön ja ilmoittakoon sen papille sanoen: 'Minun talooni näyttää ilmestyneen jotakin spitaalilaikun tapaista.'",
        36: 'Pappi käskeköön tyhjentää talon, ennen kuin menee tutkimaan laikkua, ettei kaikki, mitä talossa on, tulisi saastaiseksi. Sitten pappi menköön tutkimaan laikkua.',
        37: 'Jos hän tutkiessaan laikkua näkee laikun kohdalla talon seinissä vihertäviä tai punertavia syvennyksiä, jotka näyttävät muuta seinää matalammilta,',
        38: 'menköön talosta ulos talon ovelle ja sulkekoon talon seitsemäksi päiväksi.',
        39: 'Jos pappi palattuaan seitsemäntenä päivänä tarkastaessaan huomaa laikun levinneen talon seinissä,',
        40: 'käskeköön murtaa pois ne kivet, joissa laikkua on, ja heittää ne ulos kaupungista saastaiseen paikkaan.',
        41: 'Talo kaavittakoon sisältä ympäriinsä puhtaaksi, ja kaavittu savi heitettäköön ulos kaupungista saastaiseen paikkaan.',
        42: 'Sitten otettakoon uusia kiviä ja pantakoon entisten kivien sijaan, ja otettakoon uutta savea ja savettakoon talo sillä.',
        43: 'Jos laikku ilmestyy taloon uudestaan, sen jälkeen kun kivet ovat murretut pois ja talo on puhtaaksi kaavittu ja uudelleen savettu,',
        44: 'menköön pappi sisälle, ja jos hän tarkastaessaan huomaa laikun levinneen talossa, niin talossa on pahanlaatuinen spitaali. Se on saastainen.',
        45: 'Sen tähden talo revittäköön, sekä sen kivet että puuaines ja kaikki sen savi, ja vietäköön ne ulos kaupungista saastaiseen paikkaan.',
        46: 'Se, joka on käynyt talossa sinä aikana, jona sen oli oltava suljettuna, olkoon saastainen iltaan asti.',
        47: 'Se, joka on maannut siinä talossa, pesköön vaatteensa, ja se, joka on syönyt talossa, pesköön vaatteensa.',
        48: 'Mutta jos pappi menee sisälle ja tarkastaessaan huomaa, ettei laikku ole levinnyt talossa sen saveamisen jälkeen, julistakoon pappi talon puhtaaksi, sillä tartunta on hävinnyt.',
        49: 'Ottakoon kaksi lintua, setripuuta, helakanpunaista lankaa ja iisoppikorren talon puhdistamista varten.',
        50: 'Teurastakoon toisen linnun saviastian päällä, jossa on raikasta vettä.',
        51: 'Ottakoon setripuun, iisoppikorren ja helakanpunaisen langan ja elävän linnun, kastakoon ne teurastetun linnun vereen ja raikkaaseen veteen ja pirskottakoon sitä taloon seitsemän kertaa.',
        52: 'Puhdistakoon näin talon linnun verellä ja raikkaalla vedellä, elävällä linnulla, setripuulla, iisoppikorrella ja helakanpunaisella langalla.',
        53: 'Päästäköön sitten elävän linnun lentämään kaupungin ulkopuolelle kedolle. Toimitettuaan talolle sovituksen, se on puhdas."',
        54: 'Tämä on laki kaikkinaisesta spitaalista ja syyhystä,',
        55: 'spitaalista vaatteissa ja taloissa,',
        56: 'nystyröistä, ihottumista ja vaaleista pilkuista,',
        57: 'neuvoksi siitä, milloin mikin on saastainen, milloin puhdas. Tämä on laki spitaalista.',
    },
    15: {
        1: 'Sitten Herra puhui Moosekselle ja Aaronille sanoen:',
        2: '"Puhukaa israelilaisille ja sanokaa heille: Jos jollakulla, kenellä tahansa, on elimestään liman vuoto, hänen vuotonsa on saastainen.',
        3: 'Hänen vuotonsa saastaisuus on sellainen, että hän, sekä silloin, kun hänen elimestään vuotaa, että silloin, kun hänen elimensä pidättää vuodon, on saastainen.',
        4: 'Jokainen vuode, jossa se lepää, jolla on vuoto, tulee saastaiseksi, ja jokainen istuin, jolla hän istuu, tulee saastaiseksi.',
        5: 'Joka koskee hänen vuoteeseensa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        6: 'Joka istuu istuimelle, jolla on istunut sellainen, jolla on vuoto, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        7: 'Joka koskee sellaisen ruumiiseen, jolla on vuoto, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        8: 'Jos se, jolla on vuoto, sylkee puhtaan ihmisen päälle, tämä pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        9: 'Jokainen satula, jossa sellainen, jolla on vuoto, ratsastaa, tulee saastaiseksi.',
        10: 'Jokainen, joka koskee mihin hyvänsä, mikä on ollut hänen allaan, olkoon saastainen iltaan asti. Joka sellaista kantaa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        11: 'Jokainen, johon sellainen, jolla on vuoto, koskee, ennen kuin on huuhtonut kätensä vedessä, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        12: 'Saviastia, johon sellainen, jolla on vuoto, koskee, rikottakoon, mutta jokainen puuastia huuhdottakoon vedessä.',
        13: 'Kun se, jolla on ollut vuoto, tulee puhtaaksi vuodostaan, laskekoon puhdistumisestaan seitsemän päivää ja sitten pesköön vaatteensa ja pesköön ruumiinsa raikkaassa vedessä, niin hän on puhdas.',
        14: 'Ottakoon kahdeksantena päivänä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tulkoon Herran eteen ilmestysmajan ovelle ja antakoon ne papille.',
        15: 'Pappi uhratkoon ne, toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen vuodostaan.',
        16: 'Kun miehellä on ollut siemenvuoto, pesköön koko ruumiinsa vedessä ja olkoon saastainen iltaan asti.',
        17: 'Jokainen vaate ja jokainen nahka, johon siemenvuotoa on tullut, pestäköön vedessä ja olkoon saastainen iltaan asti.',
        18: 'Kun mies on maannut naisen kanssa ja vuodattanut siemenensä, peseytykööt vedessä ja olkoot saastaiset iltaan asti.',
        19: 'Kun naisella on vuoto, niin että verta vuotaa hänen ruumiistaan, olkoon kuukautistilassaan seitsemän päivää, ja jokainen, joka häneen koskee, olkoon saastainen iltaan asti.',
        20: 'Kaikki, minkä päällä hän lepää kuukautistilansa aikana, tulee saastaiseksi, ja kaikki, minkä päällä hän istuu, tulee saastaiseksi.',
        21: 'Jokainen, joka koskee hänen vuoteeseensa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        22: 'Jokainen, joka koskee istuimeen, mihin hyvänsä, jolla hän on istunut, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        23: 'Jos joku koskee esineeseen, joka on hänen vuoteellaan tai istuimella, jolla hän on istunut, olkoon saastainen iltaan asti.',
        24: 'Jos mies makaa hänen kanssaan ja hänen kuukautistaan tulee hänen päälleen, olkoon saastainen seitsemän päivää, ja jokainen vuode, jolla mies lepää, tulee saastaiseksi.',
        25: 'Jos naisen verenvuoto kestää kauan aikaa, vaikka ei ole hänen kuukautisaikansa, tai jos se jatkuu hänen kuukautisaikansa ohi, pidettäköön hänet koko vuotonsa ajan saastaisena kuten hänen kuukautisaikanaankin. Hän on saastainen.',
        26: 'Jokaisesta vuoteesta, jolla hän lepää vuotonsa aikana, olkoon voimassa, mitä on säädetty hänen kuukautisaikana käyttämästään vuoteesta. Jokainen istuin, jolla hän istuu, tulee saastaiseksi kuten hänen kuukautisaikanaankin.',
        27: 'Jokainen, joka niihin koskee, tulee saastaiseksi. Hän pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.',
        28: 'Mutta kun hän tulee puhtaaksi vuodostaan, laskekoon seitsemän päivää, ja sitten hän on puhdas.',
        29: 'Ottakoon kahdeksantena päivänä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tuokoon ne papille ilmestysmajan ovelle.',
        30: 'Pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen saastaisesta vuodostaan.',
        31: 'Näin teidän on varoitettava israelilaisia saastaisuudesta, etteivät he saastaisuudessaan kuolisi, jos saastuttavat minun asumukseni, joka on heidän keskellään."',
        32: 'Tämä on laki miehestä, jolla on vuoto, ja miehestä, jolla on siemenvuoto ja joka tulee siitä saastaiseksi,',
        33: 'ja naisesta, jolla on kuukautisensa, ja miehestä ja naisesta, joilla on jotakin vuotoa, sekä miehestä, joka makaa saastaisen naisen kanssa.',
    },
    16: {
        1: 'Herra puhui Moosekselle sen jälkeen, kun Aaronin kaksi poikaa oli kuollut, ne, joita kuolema oli kohdannut, kun he astuivat Herran eteen.',
        2: 'Herra sanoi Moosekselle: "Sano veljellesi Aaronille: hänen ei tule joka aika mennä pyhimpään esiripun sisäpuolelle armoistuimen eteen, joka on arkin päällä, ettei hän kuolisi, sillä minä ilmestyn pilvessä armoistuimen kohdalla.',
        3: 'Mutta näin Aaron menköön pyhimpään: hänellä olkoon mukanaan mulli syntiuhriksi ja pässi polttouhriksi,',
        4: 'ja pukekoon pyhän pellavaihokkaan ylleen, peittäköön häpynsä pellavahousuilla, vyöttäköön itsensä pellavavyöllä ja pankoon pellavaisen turbaanin päähänsä. Nämä ovat pyhät vaatteet. Pesköön ruumiinsa vedessä ja pukekoon ne ylleen.',
        5: 'Ottakoon israelilaisten seurakunnalta kaksi pukkia syntiuhriksi ja yhden pässin polttouhriksi.',
        6: 'Aaron tuokoon oman syntiuhrimullinsa ja toimittakoon sovituksen itselleen ja perheelleen.',
        7: 'Ottakoon sitten ne kaksi vuohipukkia ja asettakoon ne Herran eteen ilmestysmajan ovelle.',
        8: 'Aaron heittäköön arpaa niistä kahdesta vuohesta: toisen arvan Herralle ja toisen vapauteen.',
        9: 'Aaron tuokoon vuohen, jonka arpa määräsi Herralle, ja uhratkoon sen syntiuhriksi.',
        10: 'Mutta vuohi, jonka arpa määräsi vapauteen, asetettakoon elävänä Herran eteen, että sille toimitettaisiin sovitus ja se sitten päästettäisiin erämaahan vapauteen.',
        11: 'Sen jälkeen Aaron tuokoon oman syntiuhrimullinsa ja toimittakoon sovituksen itselleen ja perheelleen ja teurastakoon oman syntiuhrimullinsa.',
        12: 'Ottakoon sitten hiilipannun täyteen tulisia hiiliä alttarilta, joka on Herran edessä, ja kouransa täyteen survottua hyvänhajuista suitsuketta ja vieköön ne esiripun sisäpuolelle.',
        13: 'Pankoon sitten suitsukkeen tulen päälle Herran eteen, niin että suitsutus peittää pilvenä lain arkin päällä olevan armoistuimen, ettei hän kuolisi.',
        14: 'Ottakoon sitten mullin verta ja pirskottakoon sitä sormellaan armoistuimen etupuolelle. Pirskottakoon sitten armoistuimen eteen sormellaan verta seitsemän kertaa.',
        15: 'Teurastakoon sitten kansan syntiuhripukin ja vieköön sen verta esiripun sisäpuolelle ja tehköön sen verellä, niin kuin hän teki mullin verellä: pirskottakoon sitä armoistuimelle ja armoistuimen eteen.',
        16: 'Toimittakoon pyhäkölle sovituksen israelilaisten saastaisuudesta ja heidän rikoksistaan, kaikista heidän synneistään. Tehköön samoin myös ilmestysmajalle, joka on heidän luonaan keskellä heidän saastaisuuttaan.',
        17: 'Älköön ketään olko ilmestysmajassa, kun hän tulee toimittamaan sovitusta pyhimmässä, siihen asti kunnes hän sieltä lähtee ja on toimittanut sovituksen itselleen, perheelleen ja koko Israelin seurakunnalle.',
        18: 'Menköön sieltä sitten alttarin luo, joka on Herran edessä, ja toimittakoon sille sovituksen. Ottakoon mullin verta ja vuohipukin verta ja sivelköön sitä alttarin sarviin joka puolelle.',
        19: 'Pirskottakoon sormellaan sen päälle verta seitsemän kertaa ja puhdistakoon ja pyhittäköön sen israelilaisten saastaisuudesta.',
        20: 'Kun hän on toimittanut valmiiksi pyhäkön ja ilmestysmajan ja alttarin sovituksen, tuokoon elävän vuohipukin.',
        21: 'Aaron laskekoon molemmat kätensä elävän vuohen pään päälle ja tunnustakoon siinä kaikki israelilaisten pahat teot, kaikki heidän rikoksensa ja kaikki heidän syntinsä ja pankoon ne vuohen pään päälle ja lähettäköön sen sitä varten varatun miehen viemänä erämaahan.',
        22: 'Näin vuohi kantakoon kaikki heidän pahat tekonsa autioon seutuun, ja vuohi päästettäköön erämaahan.',
        23: 'Aaron menköön ilmestysmajaan ja riisukoon päältään pellavavaatteet, jotka hän oli pukenut ylleen mennessään pyhäkköön, ja jättäköön ne sinne.',
        24: 'Pesköön sitten pyhässä paikassa ruumiinsa vedellä ja pukekoon ylleen omat vaatteensa. Lähteköön sitten sieltä ja uhratkoon sekä oman polttouhrinsa että kansan polttouhrin ja toimittakoon sekä itselleen että kansalle sovituksen.',
        25: 'Polttakoon sitten syntiuhrin rasvan alttarilla.',
        26: 'Se, joka päästi vuohen vapauteen, pesköön vaatteensa ja myös ruumiinsa vedellä, ja tulkoon vasta sitten leiriin.',
        27: 'Syntiuhrimulli ja syntiuhripukki, joiden veri tuotiin sovitukseksi pyhäkköön, vietäköön leirin ulkopuolelle, ja niiden nahka, liha ja ruokasula poltettakoon tulessa.',
        28: 'Se, joka ne polttaa, pesköön sekä vaatteensa että ruumiinsa vedessä, ja tulkoon vasta sitten leiriin.',
        29: 'Tämä olkoon teille ikuinen säädös: seitsemännessä kuussa, kuukauden kymmenentenä päivänä kurittakaa itseänne paastolla älkääkä toimittako yhtään askaretta, älköön maassa syntynyt älköönkä muukalainen, joka asuu keskellänne.',
        30: 'Sillä sinä päivänä toimitetaan teille sovitus teidän puhdistamiseksenne. Te tulette puhtaiksi kaikista synneistänne Herran edessä.',
        31: 'Se olkoon teille levon päivä. Kurittakaa silloin itseänne paastolla. Se olkoon ikuinen säädös.',
        32: 'Sovituksen toimittakoon pappi, joka on voideltu ja joka on vihitty papinvirkaan isänsä sijaan. Hän pukekoon ylleen pellavavaatteet, pyhät vaatteet,',
        33: 'ja toimittakoon sovituksen kaikkeinpyhimmälle ja sovituksen ilmestysmajalle ja alttarille sekä sovituksen myös papeille ja kaikelle seurakunnan kansalle.',
        34: 'Olkoon tämä teille ikuisena säädöksenä, niin että toimitatte israelilaisille sovituksen kaikista heidän synneistään kerran vuodessa." Niin Aaron teki, kuten Herra oli Moosesta käskenyt.',
    },
    17: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Puhu Aaronille ja hänen pojilleen ja kaikille israelilaisille ja sano heille: Näin on Herra käskenyt sanoen:',
        3: 'Kuka ikinä Israelin heimosta teurastaa härän tai karitsan tai vuohen leirissä tai leirin ulkopuolella',
        4: 'eikä tuo sitä ilmestysmajan ovelle antaakseen sen uhrilahjana Herralle Herran asumuksen edessä, hänet pidettäköön vereen vikapäänä. Hän on vuodattanut verta. Mies hävitettäköön kansastaan.',
        5: 'Sen tähden israelilaiset tuokoot uhriteuraansa, jotka he ovat teurastaneet kedolla, Herran eteen ilmestysmajan ovelle papille, ja siellä uhratkoot ne rauhanuhriksi Herralle.',
        6: 'Pappi vihmokoon veren Herran alttarille ilmestysmajan oven edessä ja polttakoon rasvan suloiseksi tuoksuksi Herralle.',
        7: 'Älkööt he enää uhratko uhrejaan pukeille, joiden jäljessä he kulkevat haureudessa. Tämä olkoon heille ikuinen säädös sukupolvesta sukupolveen.',
        8: 'Sano heille: Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat keskuudessanne, uhraa polttouhrin tai teurasuhrin',
        9: 'eikä tuo sitä ilmestysmajan ovelle, Herralle uhrattavaksi, se mies hävitettäköön kansastaan.',
        10: 'Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskuudessanne, syö verta, mitä tahansa, minä käännän kasvoni sitä ihmistä vastaan, joka syö verta, ja hävitän hänet kansastaan.',
        11: 'Sillä lihan henki on sen veri, ja minä olen antanut sen teille alttarille, että se tuottaisi teille sovituksen. Sillä veri tuottaa sovituksen, koska elämä on siinä.',
        12: 'Sen tähden minä olen sanonut israelilaisille: Älköön kukaan teistä syökö verta. Älköön myöskään muukalainen, joka asuu keskuudessanne, syökö verta.',
        13: 'Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat keskuudessanne, saa pyydystetyksi syötävän metsäeläimen tai linnun, vuodattakoon sen veren maahan ja peittäköön multaan.',
        14: 'Sillä kaiken lihan henki on sen veressä sen eläessä. Sen tähden minä sanon israelilaisille: Älkää syökö minkään lihan verta. Sillä kaiken lihan henki on sen veri. Jokainen, joka sitä syö, hävitettäköön.',
        15: 'Jokainen, olipa hän maassa syntynyt tai muukalainen, joka syö itsestään kuollutta tai kuoliaaksi raadeltua eläintä, pesköön vaatteensa ja peseytyköön vedellä ja olkoon saastainen iltaan asti. Niin hän tulee puhtaaksi.',
        16: 'Mutta jos hän ei pese vaatteitaan eikä pese ruumistaan, hän joutuu syynalaiseksi."',
    },
    18: {
        1: 'Sitten Herra puhui Moosekselle sanoen:',
        2: '"Puhu israelilaisille ja sano heille: Minä olen Herra, teidän Jumalanne.',
        3: 'Älkää tehkö, kuten tehdään Egyptin maassa, jossa asuitte. Älkää myöskään tehkö, niin kuin tehdään Kanaanin maassa, johon minä teidät vien. Älkää vaeltako heidän tapojensa mukaan.',
        4: 'Vaan seuratkaa minun säädöksiäni ja noudattakaa minun käskyjäni vaeltaaksenne niiden mukaan. Minä olen Herra, teidän Jumalanne.',
        5: 'Noudattakaa käskyjäni ja säädöksiäni, sillä se ihminen, joka ne pitää, on niistä elävä. Minä olen Herra.',
        6: 'Älköön kukaan teistä yhtykö veriheimolaiseensa paljastaakseen hänen häpynsä. Minä olen Herra.',
        7: 'Isäsi häpyä ja äitisi häpyä älä paljasta. Hän on äitisi, älä hänen häpyään paljasta.',
        8: 'Älä paljasta äitipuolesi häpyä, se on isäsi häpy.',
        9: 'Älä paljasta sisaresi häpyä, olipa hän isäsi tytär tai äitisi tytär, kotona tai sen ulkopuolella syntynyt. Älä paljasta heidän häpyään.',
        10: 'Älä paljasta poikasi tyttären tai tyttäresi tyttären häpyä, sillä se on oma häpysi.',
        11: 'Älä paljasta äitipuolesi tyttären häpyä, tyttären, joka on isällesi syntynyt. Hän on sisaresi.',
        12: 'Älä paljasta isäsi sisaren häpyä. Hän on isäsi veriheimolainen.',
        13: 'Älä paljasta äitisi sisaren häpyä, sillä hän on äitisi veriheimolainen.',
        14: 'Älä paljasta setäsi häpyä, älä ryhdy hänen vaimoonsa. Hän on tätisi.',
        15: 'Älä paljasta miniäsi häpyä. Hän on poikasi vaimo, älä paljasta hänen häpyään.',
        16: 'Älä paljasta veljesi vaimon häpyä. Se on veljesi häpy.',
        17: 'Älä paljasta kenenkään muun veriheimolaisvaimon ja hänen tyttärensä häpyä, äläkä ota vaimoksi hänen poikansa tytärtä tai tyttärensä tytärtä paljastaaksesi hänen häpynsä, sillä he ovat veriheimolaisia. Se on sukurutsausta.',
        18: 'Älä ota vaimosi eläessä hänen sisartaan vaimoksesi ja paljasta hänen häpyään, sillä se tuo riidan.',
        19: 'Älä yhdy vaimoon paljastaaksesi hänen häpynsä, kun hän on saastainen kuukautisaikanaan.',
        20: 'Älä makaa lähimmäisesi vaimon kanssa, ettet saastuttaisi itseäsi.',
        21: 'Älä anna lapsiasi poltettaviksi uhrina Molokille, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.',
        22: 'Älä makaa miehenpuolen kanssa, niin kuin naisen kanssa maataan. Se on kauhistus.',
        23: 'Älä sekaannu mihinkään eläimeen, ettet siten saastuttaisi itseäsi. Älköön nainen tarjoutuko eläimelle pariutuakseen sen kanssa. Se on iljettävyys.',
        24: 'Älkää saastuttako itseänne millään näistä, sillä näillä kaikilla ovat itsensä saastuttaneet ne kansat, jotka minä karkotan teidän tieltänne.',
        25: 'Maa saastui, ja minä kostin sille sen pahat teot, niin että maa oksensi ulos asukkaansa.',
        26: 'Sen tähden noudattakaa minun käskyjäni ja säädöksiäni älkääkä tehkö mitään näistä kauhistuksista, älköön maassa syntynyt älköönkä muukalainen, joka asuu teidän keskuudessanne.',
        27: 'Sillä kaikkia näitä kauhistuksia tekivät tämän maan asukkaat, jotka olivat ennen teitä, niin että maa saastui.',
        28: 'Älkää niitä tehkö, ettei maa oksentaisi teitäkin ulos, jos te sen saastutatte, niin kuin se oksensi ulos kansan, joka oli ennen teitä.',
        29: 'Sillä jokainen, joka tekee minkä tahansa näistä kauhistuksista, hävitettäköön kansastaan, kaikki, jotka semmoista tekevät.',
        30: 'Sen tähden noudattakaa minun määräyksiäni, ettette seuraisi niitä kauhistavia tapoja, joita on seurattu ennen teitä, ettekä saastuttaisi itseänne niillä. Minä olen Herra, teidän Jumalanne."',
    },
    19: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Puhu kaikelle israelilaisten seurakunnalle ja sano heille: Olkaa pyhät, sillä minä, Herra, teidän Jumalanne, olen pyhä.',
        3: 'Jokainen teistä osoittakoon [kunnioittavaa] pelkoa äidilleen ja isälleen, ja pitäkää sapattini. Minä olen Herra, teidän Jumalanne.',
        4: 'Älkää kääntykö epäjumalien puoleen älkääkä tehkö itsellenne valettuja jumalankuvia. Minä olen Herra, teidän Jumalanne.',
        5: 'Kun uhraatte rauhanuhria Herralle, uhratkaa se niin, että hänen mielisuosionsa tulee osaksenne.',
        6: 'Syökää se samana päivänä, jona sen uhraatte, tai seuraavana päivänä, mutta mitä tähteeksi jää kolmanteen päivään, se poltettakoon tulessa.',
        7: 'Jos sitä syödään kolmantena päivänä, se on saastaista eikä otollista.',
        8: 'Joka sitä syö, joutuu syynalaiseksi, sillä hän on häväissyt Herran pyhän, ja hänet hävitettäköön kansastaan.',
        9: 'Kun korjaatte satoa maastanne, älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkää leikkuun jäljeltä.',
        10: 'Älä myöskään korjaa tyhjäksi viinitarhaasi äläkä poimi varisseita marjoja, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne.',
        11: 'Älkää varastako, älkää valehdelko älkääkä pettäkö lähimmäistänne.',
        12: 'Älkää vannoko väärin minun nimeeni, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.',
        13: 'Älä tee lähimmäisellesi vääryyttä äläkä ota mitään väkisin. Päivämiehesi palkka älköön olko hallussasi huomiseen asti.',
        14: 'Älä kiroa kuuroa äläkä pane kompastusta sokean eteen, vaan pelkää Jumalaasi. Minä olen Herra.',
        15: 'Älkää tehkö vääryyttä tuomitessanne. Älä ole puolueellinen köyhän hyväksi äläkä pidä ylhäisen puolta, vaan tuomitse lähimmäisesi oikein.',
        16: 'Älä liiku panettelijana kansasi keskellä äläkä vaani lähimmäisesi verta. Minä olen Herra.',
        17: 'Älä vihaa veljeäsi sydämessäsi, vaan nuhtele lähimmäistäsi, ettet joutuisi hänen tähtensä syynalaiseksi.',
        18: 'Älä kosta äläkä pidä vihaa kansasi lapsia vastaan, vaan rakasta lähimmäistäsi niin kuin itseäsi. Minä olen Herra.',
        19: 'Noudattakaa käskyjäni. Älä anna karjassasi kahden erilaisen eläimen pariutua, älä kylvä peltoosi kahdenlaista siementä, älköönkä kahdenlaisista langoista kudottua vaatetta tulko yllesi.',
        20: 'Jos mies makaa naisen, joka on orjatar ja toisen miehen oma eikä ole lunastettu eikä vapaaksi laskettu, rangaistakoon heitä, ei kuitenkaan kuolemalla, koska nainen ei ollut vapaa.',
        21: 'Mies tuokoon hyvityksenään Herralle vikauhripässin ilmestysmajan ovelle.',
        22: 'Kun pappi on toimittanut hänelle sovituksen vikauhripässillä Herran edessä siitä synnistä, jonka hän oli tehnyt, annetaan hänelle hänen tekemänsä synti anteeksi.',
        23: 'Kun tulette siihen maahan ja istutatte kaikenlaisia hedelmäpuita, jättäkää niiden hedelmä, niiden esinahka, koskemattomaksi. Kolmena vuotena pitäkää ne ympärileikkaamattomina, älkää niitä syökö.',
        24: 'Mutta neljäntenä vuotena pyhitettäköön kaikki niiden hedelmät ilojuhlassa Herralle.',
        25: 'Vasta viidentenä vuotena syökää niiden hedelmää. Näin te lisäätte niiden tuottoa. Minä olen Herra, teidän Jumalanne.',
        26: 'Älkää syökö mitään verineen. Älkää ennustelko merkeistä älkääkä harjoittako noituutta.',
        27: 'Älkää ajako tukkaanne päälaen ympäriltä, äläkä leikkaamalla turmele partasi reunaa.',
        28: 'Älkää viileskelkö ihoanne vainajan tähden älkääkä piirrelkö siihen tatuointeja. Minä olen Herra.',
        29: 'Älä häpäise tytärtäsi antamalla hänen tulla portoksi, ettei maa harjoittaisi haureutta ja tulisi täyteen iljettävyyttä.',
        30: 'Pitäkää sapattini ja osoittakaa pelkoa pyhäkölleni. Minä olen Herra.',
        31: 'Älkää kääntykö vainaja- ja tietäjähenkien puoleen. Älkää etsikö heitä, ettette saastuisi heistä. Minä olen Herra, teidän Jumalanne',
        32: 'Nouse harmaapään edessä ja kunnioita vanhusta sekä pelkää Jumalaasi. Minä olen Herra.',
        33: 'Kun muukalainen asuu luonasi teidän maassanne, älkää sortako häntä.',
        34: 'Muukalainen, joka asuu luonanne, olkoon niin kuin maassa syntynyt teikäläinen. Rakasta häntä niin kuin itseäsi, sillä tekin olitte muukalaisina Egyptin maassa. Minä olen Herra, teidän Jumalanne.',
        35: 'Älkää tehkö vääryyttä tuomitessanne älkääkä käyttäessänne pituus-, paino- tai tilavuusmittaa.',
        36: 'Olkoon teillä oikea vaaka, oikeat punnukset, oikea eefa-mitta ja oikea hiin-mitta. Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta.',
        37: 'Noudattakaa kaikkia käskyjäni ja kaikkia säädöksiäni ja pitäkää ne. Minä olen Herra."',
    },
    20: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Sano israelilaisille: Jos joku, kuka tahansa israelilainen tai muukalainen, joka asuu Israelissa, antaa lapsiaan Molokille, häntä rangaistakoon kuolemalla. Maan kansa kivittäköön hänet.',
        3: 'Minä käännän kasvoni sitä miestä vastaan ja hävitän hänet hänen kansastaan, koska hän on antanut Molokille lapsiaan saastuttaen pyhäkköni ja häväisten pyhän nimeni.',
        4: 'Jos maan kansa säästää sen miehen, joka antaa lapsiaan Molokille, niin etteivät he häntä surmaa,',
        5: 'niin minä itse käännän kasvoni sitä miestä vastaan ja hänen sukuaan vastaan. Hänet ja kaikki, jotka häntä seuraten ovat lähteneet haureudessa kulkemaan Molokin jäljessä, minä hävitän kansastaan.',
        6: 'Jos joku kääntyy vainaja- tai tietäjähenkien puoleen lähtien haureudessa kulkemaan niiden perässä, sitä ihmistä vastaan minä käännän kasvoni ja hävitän hänet kansastaan.',
        7: 'Pyhittäkää siis itsenne ja olkaa pyhät, sillä minä olen Herra, teidän Jumalanne.',
        8: 'Noudattakaa käskyjäni ja pitäkää ne. Minä olen Herra, joka pyhitän teidät.',
        9: 'Kuka ikinä kiroaa isäänsä tai äitiään, hänen pitää totisesti kuolla. Koska hän on kironnut isäänsä ja äitiään, hän on verivelan alainen.',
        10: 'Jos joku tekee aviorikoksen toisen miehen vaimon kanssa, jos hän tekee aviorikoksen lähimmäisensä vaimon kanssa, niin heidät, sekä aviorikoksen tehnyt mies että nainen, rangaistakoon kuolemalla.',
        11: 'Jos joku makaa äitipuolensa kanssa paljastaen isänsä hävyn, heidät molemmat rangaistakoon kuolemalla. He ovat verivelan alaisia.',
        12: 'Jos joku makaa miniänsä kanssa, rangaistakoon heidät molemmat kuolemalla. He ovat tehneet iljettävyyden ja ovat verivelan alaiset.',
        13: 'Jos joku makaa miehenpuolen kanssa, niin kuin naisen kanssa maataan, tekevät molemmat kauhistuksen. Heitä rangaistakoon kuolemalla. He ovat verivelan alaiset.',
        14: 'Jos joku ottaa vaimoksi naisen ja hänen äitinsä, se on iljettävyys. Sekä hänet että ne molemmat poltettakoon tulessa, ettei mitään iljettävyyttä olisi teidän keskuudessanne.',
        15: 'Jos joku sekaantuu eläimeen, rangaistakoon hänet kuolemalla. Eläin tappakaa.',
        16: 'Jos nainen ryhtyy eläimeen, mihin tahansa, pariutuakseen sen kanssa, niin surmaa sekä nainen että eläin. Heidät rangaistakoon kuolemalla. He ovat verivelan alaiset.',
        17: 'Jos joku ottaa vaimoksi sisarensa, isänsä tyttären tai äitinsä tyttären, ja näkee hänen häpynsä ja tämä näkee hänen häpynsä, niin se on häpeä, ja heidät hävitettäköön kansalaistensa silmistä. Hän on paljastanut sisarensa hävyn, hän on joutunut syynalaiseksi.',
        18: 'Jos joku makaa kuukautistilassa olevan naisen kanssa ja paljastaa hänen häpynsä, avaa hänen lähteensä, ja nainen paljastaa verensä lähteen, niin heidät molemmat hävitettäköön kansastaan.',
        19: 'Älä paljasta äitisi sisaren tai isäsi sisaren häpyä. Sillä se, joka niin tekee, on paljastanut veriheimolaisensa. He joutuvat syynalaisiksi.',
        20: 'Jos joku makaa setänsä vaimon kanssa, hän on paljastanut setänsä hävyn. He joutuvat syynalaisiksi. Lapsettomina he kuolkoot.',
        21: 'Jos joku ottaa vaimoksi veljensä vaimon, se on saastaisuus. Hän on paljastanut veljensä hävyn, lapsettomiksi he jääkööt.',
        22: 'Noudattakaa siis kaikkia käskyjäni ja kaikkia säädöksiäni ja pitäkää ne, ettei teitä oksentaisi ulos se maa, johon minä vien teidät asumaan.',
        23: 'Älkää vaeltako sen kansan tapojen mukaan, jonka minä karkotan teidän tieltänne. Sillä kaikkia näitä he ovat tehneet ja nostaneet minun inhoni.',
        24: 'Mutta minä sanon teille: Te saatte ottaa omaksenne heidän maansa, sillä minä annan sen teille omaksi, maan, joka vuotaa maitoa ja hunajaa. Minä olen Herra, teidän Jumalanne, joka olen teidät erottanut muista kansoista.',
        25: 'Erottakaa myös puhtaat eläimet saastaisista ja saastaiset linnut puhtaista, ettette saattaisi itseänne inhottaviksi koskemalla nelijalkaisiin eläimiin, lintuihin tai maan matelijoihin, mihin tahansa, jotka minä olen erottanut, että te pitäisitte niitä saastaisina.',
        26: 'Olkaa siis minulle pyhät, sillä minä, Herra, olen pyhä, ja minä olen teidät erottanut muista kansoista olemaan omiani.',
        27: 'Jos jossakin miehessä tai naisessa on vainaja- tai tietäjähenki, niin heitä rangaistakoon kuolemalla. Heidät kivitettäköön, he ovat verivelan alaiset."',
    },
    21: {
        1: 'Herra sanoi Moosekselle: "Puhu papeille, Aaronin pojille, ja sano heille: Pappi älköön saattako itseään saastaiseksi kenestäkään kuolleesta sukulaisestaan,',
        2: 'paitsi lähimmästä veriheimolaisestaan: äidistään, isästään, pojastaan, tyttärestään ja veljestään,',
        3: 'sekä sisarestaan, jos tämä oli neitsyt ja eli hänen luonaan eikä ollut naitu. Hänestä hän saa saastua.',
        4: 'Älköön hän, sukunsa päämies, saattako itseään saastaiseksi, ettei häpäisisi itseään.',
        5: 'Älkööt he ajako paljaaksi päälakeaan, älkööt leikatko partansa reunaa älköötkä viileskelkö ruumistaan.',
        6: 'Olkoot Jumalalleen pyhät älköötkä häväiskö Jumalansa nimeä, sillä he uhraavat Herran uhreja, Jumalansa leipää. Sen tähden olkoot pyhät.',
        7: 'Älkööt ottako vaimoksi porttoa tai häväistyä naista älköötkä ottako miehensä hylkäämää vaimoa, sillä pappi on pyhä Jumalalleen.',
        8: 'Sinun on pidettävä häntä pyhänä, koska hän uhraa sinun Jumalasi leipää. Hän olkoon sinulle pyhä, sillä minä, Herra, joka pyhitän teidät, olen pyhä.',
        9: 'Jos papin tytär häpäisee itsensä haureudella, hän häpäisee isänsä. Hänet poltettakoon tulessa.',
        10: 'Pappi, joka on ylimmäinen veljiensä seassa, jonka pään päälle voiteluöljy on vuodatettu ja joka on vihitty virkaansa pukemalla hänet pyhiin vaatteisiin, älköön päästäkö tukkaansa hajalle älköönkä reväiskö vaatteitaan.',
        11: 'Älköön hän myöskään menkö minkään kuolleen luo. Isästäänkään tai äidistään hän älköön saastuko.',
        12: 'Älköön hän lähtekö pyhäköstä, ettei hän häpäisisi Jumalansa pyhäkköä, sillä hänessä on hänen Jumalansa voiteluöljyn vihkimys. Minä olen Herra.',
        13: 'Hän ottakoon vaimokseen neitsyen.',
        14: 'Leskeä, hylättyä vaimoa, häväistyä naista tai porttoa hän älköön ottako, vaan ottakoon vaimokseen neitsyen omasta suvustaan,',
        15: 'ettei häpäisisi jälkeläisiään suvussaan. Sillä minä olen Herra, joka pyhitän hänet."',
        16: 'Herra puhui Moosekselle sanoen:',
        17: '"Puhu Aaronille ja sano: jos jossakussa jälkeläisistäsi tulevissa sukupolvissa on jokin vamma, älköön hän lähestykö uhraamaan Jumalansa leipää.',
        18: 'Älköön uhraamaan lähestykö kukaan, jossa on jokin vamma, älköön kukaan sokea tai ontuva, kukaan kasvoiltaan tai jäseniltään muodoton,',
        19: 'jalkansa tai kätensä taittanut,',
        20: 'kyttyräselkäinen, surkastunut, silmävikainen, ihotautinen, rupinen tai kuohittu.',
        21: 'Pappi Aaronin jälkeläisistä älköön kukaan, jossa on jokin vamma, lähestykö uhraamaan Herran uhreja. Koska hänessä on vamma, älköön sellainen lähestykö uhraamaan Jumalansa leipää.',
        22: 'Syököön kuitenkin Jumalansa leipää, sekä korkeasti pyhää että pyhää.',
        23: 'Älköön kuitenkaan tulko esiripun luo älköönkä lähestykö alttaria, koska hänessä on vamma, ettei hän häpäisisi minun pyhäkköäni. Sillä minä olen Herra, joka pyhitän heidät."',
        24: 'Mooses sanoi tämän Aaronille ja hänen pojilleen ja kaikille israelilaisille.',
    },
    22: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Käske Aaronia ja hänen poikiaan pyhästi käsittelemään israelilaisten pyhiä lahjoja, heidän minulle pyhittämiään, etteivät he häpäisisi pyhää nimeäni. Minä olen Herra.',
        3: 'Sano heille polvesta polveen: Jos kuka tahansa jälkeläisistänne saastuneena ollessaan lähestyy niitä pyhiä lahjoja, joita israelilaiset pyhittävät Herralle, hänet hävitettäköön kasvojeni edestä.',
        4: 'Minä olen Herra. Älköön kukaan Aaronin jälkeläinen, joka on spitaalinen tai jolla on vuoto, syökö pyhistä lahjoista, ennen kuin on tullut puhtaaksi. Joka koskee johonkin kuolleesta saastuneeseen tai jolla on siemenvuoto,',
        5: 'tai joka koskee mihin tahansa pikkueläimeen, josta saastuu, tai ihmiseen, josta saastuu, olipa sen saastaisuus mitä laatua tahansa,',
        6: 'niin jokainen, joka koskee johonkin sellaiseen, olkoon saastainen iltaan asti älköönkä syökö pyhistä lahjoista, ellei ole pessyt ruumistaan vedellä.',
        7: 'Mutta kun aurinko on laskenut, hän on puhdas. Sitten syököön pyhistä lahjoista, sillä se on hänen ruokaansa.',
        8: 'Itsestään kuollutta tai kuoliaaksi raadeltua eläintä älköön syökö, ettei saastuisi. Minä olen Herra.',
        9: 'Noudattakoot määräyksiäni, etteivät joutuisi syynalaisiksi pyhitetyn tähden ja kuolisi sen vuoksi, että häpäisevät pyhitetyn. Minä olen Herra, joka pyhitän heidät.',
        10: 'Kukaan muu kuin pappi älköön syökö pyhästä lahjasta. Älköön muukalainen tai papin luona asuva tai päiväpalkkalainen syökö pyhästä lahjasta.',
        11: 'Mutta kun pappi ostaa rahallaan orjan, saakoon tämä siitä syödä. Samoin hänen kodissaan syntyneet orjat syökööt hänen ruokaansa.',
        12: 'Jos papin tytär tulee muukalaisen miehen vaimoksi, älköön hän syökö pyhistä uhrilahjoista.',
        13: 'Mutta jos papin tytär tulee leskeksi tai hylätyksi ja on lapseton ja tulee takaisin isänsä taloon ja asuu siellä niin kuin nuoruudessaan, syököön isänsä ruokaa. Mutta kukaan muukalainen älköön sitä syökö.',
        14: 'Jos joku erehdyksessä syö pyhästä lahjasta, korvatkoon papille pyhän lahjan ja pankoon siihen vielä lisäksi viidennen osan sen arvosta.',
        15: 'Älkööt papit häväiskö israelilaisten pyhiä lahjoja, joita nämä antavat Herralle,',
        16: 'älköötkä saattako heitä syynalaisiksi ja vikapäiksi sallimalla heidän syödä pyhiä lahjojaan. Sillä minä olen Herra, joka pyhitän heidät."',
        17: 'Herra puhui Moosekselle sanoen:',
        18: '"Puhu Aaronille ja hänen pojilleen ja kaikille israelilaisille ja sano heille: Kuka ikinä Israelin heimosta tai muukalaisista Israelissa tuo polttouhriksi uhrilahjansa, olipa se mikä hyvänsä lupausuhri tai vapaaehtoinen uhri, jonka he tuovat Herralle,',
        19: 'niin tuokaa sellainen uhri, että hänen mielisuosionsa tulee osaksenne: virheetön urospuoli naudoista, lampaista tai vuohista.',
        20: 'Mutta yhtään eläintä, jossa on vamma, älkää tuoko, sillä siitä hänen mielisuosionsa ei tule teidän osaksenne.',
        21: 'Jos joku tuo Herralle rauhanuhrin naudoista tai lampaista, joko lupausta täyttääkseen tai vapaaehtoisena uhrina, olkoon eläin virheetön ollakseen otollinen. Älköön siinä olko mitään vammaa.',
        22: 'Sokeaa tai raajarikkoa tai silvottua tai paiseista tai ihotautista tai rupista älkää Herralle tuoko, älkääkä sellaisia asettako alttarille uhriksi Herralle.',
        23: 'Härän tai lampaan, joka on jäseniltään muodoton tai vaivainen, saat uhrata vapaaehtoisena uhrina, mutta lupausuhriksi se ei ole otollinen.',
        24: 'Älkää uhratko Herralle eläintä, joka on kuohittu puristamalla, musertamalla, repimällä tai leikkaamalla. Älkää tehkö maassanne sellaista.',
        25: 'Älkää myöskään ostako muukalaiselta mitään sellaisia eläimiä tuodaksenne niitä Jumalanne ruoaksi. Sillä ne ovat turmeltuja, niissä on vamma. Niistä ei tule osaksenne mielisuosiota."',
        26: 'Herra puhui Moosekselle sanoen:',
        27: '"Kun vasikka, karitsa tai kili on syntynyt, olkoon se emänsä luona seitsemän päivää. Mutta kahdeksannesta päivästä alkaen se on otollinen uhrilahjaksi Herralle.',
        28: 'Älkää teurastako samana päivänä nautaa vasikkansa kanssa tai lammasta karitsansa kanssa.',
        29: 'Kun uhraatte Herralle rauhanuhrin, uhratkaa se niin, että hänen mielisuosionsa tulee osaksenne.',
        30: 'Syötäköön se samana päivänä. Älkää jättäkö siitä mitään seuraavaan aamuun. Minä olen Herra.',
        31: 'Noudattakaa siis käskyjäni ja pitäkää ne. Minä olen Herra.',
        32: 'Älkää häväiskö pyhää nimeäni: minä tahdon olla pyhä israelilaisten keskellä. Minä olen Herra, joka pyhitän teidät',
        33: 'ja joka vein teidät pois Egyptin maasta, ollakseni Jumalanne. Minä olen Herra."',
    },
    23: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Puhu israelilaisille ja sano heille: Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset, minun juhlani, ovat nämä:',
        3: 'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, pyhä kokous. Silloin älkää toimittako yhtään askaretta. Se on Herran sapatti, missä asuttekin.',
        4: 'Nämä ovat Herran juhlat, pyhät kokoukset, jotka teidän on kuulutettava määräajallaan:',
        5: 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, iltahämärässä, on pääsiäinen Herran kunniaksi.',
        6: 'Saman kuukauden viidentenätoista päivänä on happamattoman leivän juhla Herran kunniaksi. Syökää happamatonta leipää seitsemän päivää.',
        7: 'Ensimmäisenä päivänä olkoon teillä pyhä kokous, silloin älkää toimittako mitään arkiaskaretta.',
        8: 'Tuokaa Herralle uhri seitsemänä päivänä. Seitsemäntenä päivänä on pyhä kokous. Silloin älkää toimittako mitään arkiaskaretta."',
        9: 'Herra puhui Moosekselle sanoen:',
        10: '"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä teille annan, ja leikkaatte sen viljaa, niin viekää papille viljastanne ensimmäinen lyhde.',
        11: 'Hän toimittakoon lyhteen heilutuksen Herran edessä, että hänen mielisuosionsa tulisi osaksenne. Pappi toimittakoon heilutuksen sapatin jälkeisenä päivänä.',
        12: 'Sinä päivänä, jona lyhteenne heilutus toimitetaan, uhratkaa virheetön, vuoden vanha karitsa polttouhriksi Herralle.',
        13: 'Uhratkaa myös siihen kuuluvana ruokauhrina kaksi kymmenesosaa ydinjauhoja öljyyn sekoitettuna, uhrina, suloisena tuoksuna Herralle, sekä siihen kuuluvana juomauhrina neljännes hiin-mittaa viiniä.',
        14: 'Älkääkä syökö ensi sadon leipää, paahdettuja jyviä tai tuleentumatonta viljaa ennen sitä päivää, jona tuotte uhrilahjan Jumalallenne. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.',
        15: 'Sitten laskekaa sapatin jälkeisestä päivästä, siitä päivästä, jona toitte heilutuslyhteen, seitsemän täyttä viikkoa,',
        16: 'laskekaa viisikymmentä päivää seitsemännen sapatin jälkeiseen päivään asti. Sitten tuokaa Herralle uusi ruokauhri.',
        17: 'Sieltä, missä asutte, tuokaa heilutusleiväksi kaksi leipäkakkua, jotka on leivottava happamena kahdesta kymmenesosasta ydinjauhoja, Herralle ensi sadon lahjaksi.',
        18: 'Tuokaa leipänne ohella seitsemän virheetöntä, vuoden vanhaa karitsaa ja mulli sekä kaksi pässiä. Ne olkoot ruoka- ja juomauhreineen polttouhri Herralle, suloisesti tuoksuva uhri Herralle.',
        19: 'Uhratkaa vuohipukki syntiuhriksi sekä kaksi vuoden vanhaa karitsaa rauhanuhriksi.',
        20: 'Pappi toimittakoon niiden ja ensi sadon leivän sekä kahden karitsan heilutuksen Herran edessä. Ne olkoot Herralle pyhät ja papille tulevat.',
        21: 'Kuuluttakaa pyhä kokous juuri siksi päiväksi. Älkää toimittako silloin mitään arkiaskaretta. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.',
        22: 'Kun korjaatte eloa maastanne, älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkää leikkuun jälkeen, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne."',
        23: 'Herra puhui Moosekselle sanoen:',
        24: '"Puhu israelilaisille ja sano: Seitsemännessä kuussa, kuukauden ensimmäisenä päivänä, pitäkää sapattilepo, muistojuhla torvea soittaen, pyhä kokous.',
        25: 'Älkää silloin toimittako mitään arkiaskaretta, vaan tuokaa uhri Herralle."',
        26: 'Herra puhui Moosekselle sanoen:',
        27: '"Tämän seitsemännen kuun kymmenentenä päivänä on sovituspäivä. Pitäkää silloin pyhä kokous, kurittakaa itseänne paastolla ja tuokaa Herralle uhri.',
        28: 'Älkää toimittako yhtään askaretta sinä päivänä, sillä se on sovituspäivä, jolloin teille toimitetaan sovitus Herran, Jumalanne, edessä.',
        29: 'Sillä jokainen, joka sinä päivänä ei kurita itseään paastolla, hävitettäköön kansastaan.',
        30: 'Jokaisen, joka sinä päivänä toimittaa jotakin askaretta, minä hävitän hänen kansastaan.',
        31: 'Älkää silloin toimittako yhtään askaretta. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.',
        32: 'Se on oleva teille levon päivä. Kurittakaa itseänne paastolla. Kuukauden yhdeksäntenä päivänä illalla, illasta iltaan, pitäkää tämä sapatti."',
        33: 'Herra puhui Moosekselle sanoen:',
        34: '"Puhu israelilaisille ja sano: Tämän seitsemännen kuun viidentenätoista päivänä on lehtimajanjuhla Herran kunniaksi. Se kestää seitsemän päivää.',
        35: 'Ensimmäisenä päivänä pidettäköön pyhä kokous. Älkää silloin toimittako mitään arkiaskaretta.',
        36: 'Seitsemänä päivänä tuokaa uhri Herralle. Kahdeksantena päivänä olkoon teillä pyhä kokous, ja tuokaa uhri Herralle. Se on juhlakokous, älkää silloin toimittako mitään arkiaskaretta.',
        37: 'Nämä ovat Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset tuodaksenne Herralle uhreja: polttouhreja ja ruokauhreja, teurasuhreja ja juomauhreja, kunakin päivänä sen päivän uhrit.',
        38: 'Nämä ovat Herran sapattien ja teidän muiden lahjojenne ja kaikkien lupausuhrienne ja kaikkien vapaaehtoisten uhrienne lisäksi, joita te Herralle annatte.',
        39: 'Seitsemännen kuukauden viidentenätoista päivänä, kun te olette korjanneet maan sadon, viettäkää Herran juhlaa seitsemän päivää. Ensimmäinen päivä on levon päivä, ja myös kahdeksas päivä on levon päivä.',
        40: 'Ensimmäisenä päivänä ottakaa puista ihania hedelmiä, palmunoksia ja tuuheiden puiden lehviä sekä pajuja purojen varsilta, ja pitäkää iloa seitsemän päivää Herran, Jumalanne edessä.',
        41: 'Viettäkää sitä juhlana Herran kunniaksi seitsemän päivää vuodessa. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen. Viettäkää se seitsemännessä kuussa.',
        42: 'Seitsemän päivää asukaa lehtimajoissa. Kaikki Israelissa syntyneet asukoot lehtimajoissa,',
        43: 'että jälkeläisenne tietäisivät, kuinka minä annoin israelilaisten asua lehtimajoissa, kun vein heidät pois Egyptin maasta. Minä olen Herra, teidän Jumalanne."',
        44: 'Mooses ilmoitti israelilaisille nämä Herran juhla-ajat.',
    },
    24: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Käske israelilaisia tuomaan sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput voidaan aina nostaa paikoilleen.',
        3: 'Esiripun ulkopuolella, joka on lain arkin edessä ilmestysmajassa, Aaron hoitakoon sitä niin, että se palaa aina illasta aamuun Herran edessä. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen.',
        4: 'Aidosta kullasta valmistetun seitsenhaaraisen lampun lamppuja hän hoitakoon niin, että ne palavat aina Herran edessä.',
        5: 'Ota ydinjauhoja ja leivo niistä kaksitoista leipäkakkua. Jokaisessa kakussa olkoon jauhoja kaksi kymmenesosaa.',
        6: 'Lado ne päällekkäin kahteen pinoon, kuusi pinoonsa, aidosta kullasta valmistetulle pöydälle Herran eteen.',
        7: 'Pane pinojen päälle puhdasta suitsuketta. Leivät ovat muistouhri, tuliuhri Herralle.',
        8: 'Sapatti sapatilta hän asettakoon ne aina Herran eteen israelilaisten antina. Se on ikuinen liitto.',
        9: 'Ne olkoot Aaronin ja hänen poikiensa. He syökööt ne pyhässä paikassa, sillä ne ovat korkeasti pyhät. Ne ovat hänen ikuinen osuutensa Herran uhreista."',
        10: 'Erään israelilaisen vaimon poika, jonka isä oli egyptiläinen mies, oli lähtenyt maasta israelilaisten mukana. Tämän israelilaisen vaimon poika ja muuan israelilainen mies riitelivät keskenään leirissä.',
        11: 'Israelilaisen vaimon poika pilkkasi Herran nimeä ja kirosi sitä. Silloin he toivat hänet Mooseksen eteen. Hänen äitinsä nimi oli Selomit, Dibrin tytär, Daanin sukukunnasta.',
        12: 'He panivat hänet vankilaan, kunnes heille ilmoitettaisiin Herran vastaus.',
        13: 'Herra puhui Moosekselle sanoen:',
        14: '"Vie kiroaja leirin ulkopuolelle, ja kaikki, jotka kuulivat sen, laskekoot kätensä hänen päänsä päälle, ja koko kansa kivittäköön hänet.',
        15: 'Puhu israelilaisille ja sano: Kuka ikinä Jumalaansa kiroaa, se joutuu syynalaiseksi.',
        16: 'Sitä, joka Herran nimeä pilkkaa, rangaistakoon kuolemalla. Koko kansa kivittäköön hänet kuoliaaksi. Olipa se muukalainen tai maassa syntynyt, joka pilkkaa Herran nimeä, hänet surmattakoon.',
        17: 'Jos joku lyö kuoliaaksi ihmisen, kenet hyvänsä, häntä rangaistakoon kuolemalla.',
        18: 'Mutta joka lyö kuoliaaksi kotieläimen, korvatkoon sen: henki hengestä.',
        19: 'Joka tuottaa lähimmäiselleen vamman, sille tehtäköön, niin kuin hänkin oli tehnyt:',
        20: 'ruhje ruhjeesta, silmä silmästä, hammas hampaasta. Saman vamman, jonka hän on toiselle tuottanut, saakoon hän itsekin.',
        21: 'Joka lyö kuoliaaksi kotieläimen, korvatkoon sen. Mutta se, joka lyö kuoliaaksi ihmisen, surmattakoon.',
        22: 'Sama laki olkoon teillä, niin muukalaisella kuin maassa syntyneelläkin. Sillä minä olen Herra, teidän Jumalanne."',
        23: 'Mooses puhui näin israelilaisille. Niin he veivät kiroajan leirin ulkopuolelle ja kivittivät hänet kuoliaaksi. Näin israelilaiset tekivät, kuten Herra oli Moosesta käskenyt.',
    },
    25: {
        1: 'Herra puhui Moosekselle Siinain vuorella sanoen:',
        2: '"Puhu israelilaisille ja sano heille: Kun tulette siihen maahan, jonka minä teille annan, pitäköön maa sapattia Herran kunniaksi.',
        3: 'Kuutena vuotena kylvä peltosi ja kuutena vuotena leikkaa viinitarhasi ja korjaa niiden sato.',
        4: 'Seitsemäntenä vuotena sen sijaan olkoon maalla levon aika, sapatti Herran kunniaksi. Älä silloin kylvä peltoasi äläkä leikkaa viinitarhaasi.',
        5: 'Leikatun viljasi jälkikasvua älä leikkaa. Älä myöskään poimi viinirypäleitä, jotka ovat kasvaneet leikkaamattomissa viinipuissasi. Olkoon maalla silloin lepovuosi.',
        6: 'Se, mitä itsestään kasvaa maan levätessä, olkoon teille ruoaksi, sinulle itsellesi, palvelijallesi ja palvelijattarellesi, päiväpalkkalaisellesi ja muukalaisille, jotka asuvat kanssasi.',
        7: 'Karjallesi ja metsäeläimille maassasi olkoon kaikki maan sato ruuaksi.',
        8: 'Laske seitsemän vuosiviikkoa: seitsemän kertaa seitsemän vuotta, niin että seitsemän vuosiviikon aika on neljäkymmentä yhdeksän vuotta.',
        9: 'Seitsemännessä kuussa, kuukauden kymmenentenä päivänä anna torven raikuen soida. Sovituspäivänä antakaa torven soida koko maassanne.',
        10: 'Pyhittäkää viideskymmenes vuosi ja julistakaa vapautus maassa kaikille sen asukkaille. Se olkoon teille riemuvuosi. Jokainen teistä saa silloin palata perintömaalleen ja sukunsa luo.',
        11: 'Riemuvuosi olkoon teille viideskymmenes vuosi. Älkää silloin kylväkö älkääkä jälkikasvua leikatko. Älkää myöskään poimiko, mitä leikkaamattomissa viinipuissa on kasvanut.',
        12: 'Sillä se on riemuvuosi. Olkoon se teille pyhä. Syökää sen sato pellolta.',
        13: 'Riemuvuotena saa jokainen teistä palata perintömaalleen.',
        14: 'Jos myyt jotakin lähimmäisellesi tai ostat jotakin lähimmäiseltäsi, älkää tehkö vääryyttä toinen toisellenne,',
        15: 'vaan maksa lähimmäisellesi riemuvuoden jälkeisten vuosien luvun mukaan. Satovuosien luvun mukaan hän saakoon sinulta.',
        16: 'Maksa sitä suurempi hinta, mitä useampia vuosia on, ja maksa sitä pienempi hinta, mitä vähemmän vuosia on, sillä sadon määrän hän myy sinulle.',
        17: 'Älköön teistä kukaan tehkö vääryyttä lähimmäiselleen, vaan pelkää Jumalaasi, sillä minä olen Herra, teidän Jumalanne.',
        18: 'Sen tähden pitäkää käskyni ja noudattakaa säädöksiäni ja pitäkää ne, niin saatte turvallisesti asua maassa.',
        19: 'Maa on antava hedelmänsä, ja teillä on kyllin syötävää, ja te saatte turvallisesti asua siinä.',
        20: "Jos te sanotte: 'Mitä syömme seitsemäntenä vuotena, kun meidän ei ole lupa kylvää eikä korjata satoamme?'",
        21: 'Niin minä käsken siunaukseni kuudentena vuotena tulemaan teille, niin että se tuottaa teille kolmen vuoden sadon.',
        22: 'Kun kylvätte kahdeksantena vuotena, teillä on vielä vanhaa satoa syödäksenne. Teillä on vanhaa satoa syödäksenne siihen asti, kunnes yhdeksännen vuoden sato on saatu.',
        23: 'Älköön myytäkö maata ainaiseksi, sillä maa on minun ja te olette muukalaisia ja vieraita minun luonani.',
        24: 'Kaikessa siinä maassa, jonka te saatte perintömaaksenne, antakaa oikeus maan sukulunastamiseen.',
        25: 'Jos veljesi köyhtyy ja myy perintömaatansa, hänen lähin sukulunastajansa tulkoon ja lunastakoon sen, minkä hänen veljensä on myynyt.',
        26: 'Mutta jos jollakulla ei ole sukulunastajaa, mutta hän itse voi hankkia niin paljon, kuin lunastukseen tarvitaan,',
        27: 'laskekoon, kuinka monta vuotta on kulunut myymisestä, ja maksakoon jäljellä olevasta ajasta miehelle, jolle hän myi, ja palatkoon perintömaalleen.',
        28: 'Mutta jos hän ei voi hankkia niin paljon, kuin maksamiseen tarvitaan, niin jääköön ostajalle se, minkä hän on myynyt, riemuvuoteen asti. Mutta riemuvuotena se on vapaa. Sitten hän palatkoon perintömaalleen.',
        29: 'Jos joku myy asuinrakennuksen muureilla varustetussa kaupungissa, olkoon hänellä oikeus lunastaa se vuoden kuluessa siitä, kun hän sen myi. Sen ajan kestää hänen sukulunastusoikeutensa.',
        30: 'Mutta jollei sitä lunasteta, ennen kuin vuosi on kulunut umpeen, jääköön talo muureilla varustetussa kaupungissa ainaiseksi ostajalle ja hänen suvulleen tulematta vapaaksi riemuvuotena.',
        31: 'Mutta talot kylissä, joiden ympärillä ei ole muuria, luettakoon peltomaaksi. Ne olkoot lunastettavissa. Ne tulevat vapaiksi riemuvuotena.',
        32: 'Leeviläisillä olkoon kuitenkin ikuinen oikeus talojen lunastamiseen niissä kaupungeissa, jotka ovat heidän perintöomaisuuttaan.',
        33: 'Jos joku leeviläinen käyttää lunastusoikeutta, niin myyty talo kaupungissa, joka on leeviläistä perintöomaisuutta, palautuu riemuvuotena vapaaksi. Sillä talot leeviläiskaupungeissa ovat heidän perintöomaisuuttaan israelilaisten keskuudessa.',
        34: 'Heidän kaupunkeihinsa kuuluvaa laidunmaata älköön myytäkö, sillä se on heidän ikuista perintöomaisuuttaan.',
        35: 'Jos veljesi luonasi köyhtyy eikä jaksa pysyä pystyssä, tue häntä samoin kuin muukalaista tai talossasi asuvaa. Hän eläköön luonasi.',
        36: 'Älä ota korkoa tai voittoa häneltä, vaan pelkää Jumalaasi ja anna veljesi elää luonasi.',
        37: 'Älä anna hänelle rahaasi korolle äläkä ota elintarpeista voittoa.',
        38: 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta antaakseni teille Kanaanin maan ja ollakseni Jumalanne.',
        39: 'Jos veljesi luonasi köyhtyy ja myy itsensä sinulle, älä pane häntä orjan työhön,',
        40: 'vaan hän olkoon päiväpalkkalaisena ja loisena luonasi. Riemuvuoteen asti hän palvelkoon sinua.',
        41: 'Silloin hän lähteköön luotasi vapaana, hän ja hänen lapsensa hänen kanssaan, ja palatkoon sukunsa luo ja isiensä perintömaalle.',
        42: 'Sillä he ovat palvelijoitani, jotka minä vein pois Egyptin maasta. Sen tähden älköön heitä orjan tavalla myytäkö.',
        43: 'Älä hallitse heitä kovuudella, vaan pelkää Jumalaasi.',
        44: 'Mutta orjasi ja orjattaresi, jotka hankit itsellesi, ostakaa kansoista, jotka asuvat ympärillänne.',
        45: 'Tai ostakaa ne luonanne asuvien suojattien lapsista ja heidän sukulaisistaan, jotka ovat luonanne ja jotka ovat heille syntyneet maassanne. He olkoot perintöomaisuuttanne.',
        46: 'Jättäkää heidät jälkeenne perinnöksi lapsillenne, pysyväksi perintöomaisuudeksi. Heitä saatte pitää ainaisesti orjinanne. Mutta veljistänne, israelilaisista, älä hallitse ketään kovuudella.',
        47: 'Jos luonasi asuva muukalainen tai suojatti tulee varoihin veljesi köyhtyessä hänen luonaan, niin että hän myy itsensä luonasi asuvalle muukalaiselle, suojatille tai jollekin muukalaisen suvun jäsenelle,',
        48: 'olkoon hän sen jälkeen, kun hän myi itsensä, lunastettavissa. Joku hänen veljistään lunastakoon hänet.',
        49: 'Tai lunastakoon hänet hänen setänsä, setänsä poika tai joku veriheimolainen hänen suvustaan. Tai jos hän tulee varoihin, lunastakoon itse itsensä.',
        50: 'Hänen on laskettava yhdessä ostajansa kanssa, kuinka pitkä aika on riemuvuoteen siitä vuodesta, jolloin hän myi itsensä hänelle. Hänen myyntihintansa jaettakoon vuosien luvulla. Hänen palvelusaikansa laskettakoon samanarvoiseksi kuin päiväpalkkalaisen.',
        51: 'Jos hänellä on vielä monta vuotta jäljellä, maksakoon takaisin lunastushintanaan niitä vastaavan osan siitä summasta, jolla hänet ostettiin.',
        52: 'Mutta jos vain vähän vuosia on jäljellä riemuvuoteen, laskekoon ostaja ne hänen kanssaan, ja hän maksakoon lunastushintansa sen mukaan, kuin hänellä on vuosia jäljellä.',
        53: 'Palvelkoon vuosikaupalla otetun päiväpalkkalaisen tavalla häntä, mutta älköön tämä kovuudella hallitko häntä silmiesi edessä.',
        54: 'Mutta jos häntä ei näin lunasteta, hän tulkoon riemuvuotena vapaaksi, hän itse ja hänen lapsensa hänen kanssaan.',
        55: 'Sillä israelilaiset ovat minun palvelijoitani. He ovat palvelijani, jotka minä vein pois Egyptin maasta. Minä olen Herra, teidän Jumalanne."',
    },
    26: {
        1: '"Älkää tehkö itsellenne epäjumalia. Älkää pystyttäkö itsellenne jumalankuvia tai patsaita. Älkää myöskään asettako maahanne kiviä, joissa on kuvia, kumartaaksenne niitä, sillä minä olen Herra, teidän Jumalanne.',
        2: 'Pitäkää sapattini ja osoittakaa pelkoa pyhäkölleni. Minä olen Herra.',
        3: 'Jos te vaellatte säädöksieni mukaan ja noudatatte käskyjäni ja pidätte ne,',
        4: 'minä annan teille sateen ajallaan, niin että maa antaa satonsa ja kedon puut kantavat hedelmänsä.',
        5: 'Silloin puiminen kestää teillä viininkorjuuseen asti, ja viininkorjuu kestää kylvöön asti. Teillä on kyllin leipää syödäksenne, ja saatte asua turvallisesti maassanne.',
        6: 'Minä annan rauhan maallenne, ja te saatte levätä, eikä kukaan ole teille pelkona. Minä hävitän pahat pedot maastanne, eikä miekka käy maanne yli.',
        7: 'Te ajatte pakoon vihollisenne, ja he kaatuvat miekkaan edessänne.',
        8: 'Viisi teistä ajaa pakoon sata, ja sata teistä ajaa pakoon kymmenentuhatta. Teidän vihollisenne kaatuvat miekkaan teidän edessänne.',
        9: 'Minä käännän kasvoni teidän puoleenne ja teen teidät hedelmällisiksi ja annan teidän lisääntyä. Minä pidän liittoni teidän kanssanne.',
        10: 'Te saatte syödä vanhaa, viime vuoden satoa, ja te joudutte viemään vanhan pois uuden tieltä.',
        11: 'Minä panen asumukseni keskuuteenne enkä vieroksu teitä.',
        12: 'Minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja te olette minun kansani.',
        13: 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta, olemasta heidän orjinaan, ja minä mursin rikki teidän ikeenne puut ja annoin teidän kulkea pystypäin.',
        14: 'Mutta jos te ette kuule minua ettekä pidä kaikkia näitä käskyjä,',
        15: 'vaan hylkäätte määräykseni ja sielunne luopuu säädöksistäni, niin ettette pidä kaikkia käskyjäni, vaan rikotte liittoni,',
        16: 'minäkin teen teille samoin. Minä rankaisen teitä hirveillä onnettomuuksilla, hivuttavalla taudilla ja kuumeella, jotka sumentavat silmänne ja näännyttävät sielunne. Te kylvätte siemenenne turhaan, sillä vihollisenne syövät sen.',
        17: 'Minä käännän kasvoni teitä vastaan, ja teidän vihollisenne voittavat teidät. Teidän vihamiehenne hallitsevat teitä, ja te pakenette, vaikka kukaan ei aja teitä takaa.',
        18: 'Jos ette sittenkään kuule minua, niin minä vielä kuritan teitä seitsenkertaisesti syntienne tähden.',
        19: 'Minä murran ylpeän uhmanne. Minä teen taivaanne raudankovaksi ja maanne vasken kaltaiseksi.',
        20: 'Teidän voimanne kuluu hukkaan, sillä teidän maanne ei suo satoaan eivätkä maan puut anna hedelmäänsä.',
        21: 'Jos te sittenkin käytte minua vastaan ettekä tahdo kuulla minua, minä lyön teitä vielä seitsenkertaisesti syntienne mukaan.',
        22: 'Minä lähetän keskuuteenne metsän pedot riistämään teiltä lapsenne, raatelemaan karjaanne ja vähentämään lukuanne, niin että tienne tulevat autioiksi.',
        23: 'Jos te ette vielä tästäkään kurituksestani ojennu, vaan käytte yhä minua vastaan,',
        24: 'niin minäkin käyn teitä vastaan ja lyön teitä seitsenkertaisesti syntienne tähden.',
        25: 'Minä saatan kimppuunne miekan, joka kostaa rikotun liiton. Kun kokoonnutte kaupunkeihinne, lähetän keskuuteenne ruttotaudin, ja teidän täytyy antautua vihollisen valtaan.',
        26: "Kun murran teiltä leivän tuen, kymmenen vaimoa paistaa leipänne yhdessä uunissa. He tuovat kotiin leipänne vaa'alla punnittuna. Kun sen syötte, ette tule ravituiksi.",
        27: 'Jos ette vielä sittenkään kuule minua, vaan yhä käytte minua vastaan,',
        28: 'minäkin kiivastuksessani käyn teitä vastaan ja kuritan teitä seitsenkertaisesti syntienne tähden.',
        29: 'Te syötte poikienne lihaa, ja tyttärienne lihaa te syötte.',
        30: 'Minä kukistan uhrikukkulanne ja hävitän auringonpatsaanne ja panen ruumiinne epäjumalienne ruumiiden päälle, ja sieluni inhoaa teitä.',
        31: 'Minä teen kaupunkinne raunioiksi ja hävitän pyhäkkönne enkä mielisty uhrienne tuoksuun.',
        32: 'Minä hävitän maan, niin että vihollisenne, jotka siinä asuvat, siitä tyrmistyvät.',
        33: 'Mutta teidät minä hajotan pakanakansojen sekaan ja ajan teitä takaa paljastetulla miekalla, ja maanne tulee autioksi ja kaupunkinne raunioiksi.',
        34: 'Silloin maa saa hyvityksen sapateistaan, niin kauan se on autiona ja te olette vihollistenne maassa. Silloin maa lepää ja saa hyvityksen sapateistaan.',
        35: 'Kun se on autiona, se saa levätä nauttien sitä lepoa, jota se ei saanut sapatteinanne asuessanne siinä.',
        36: 'Niille teistä, jotka jäävät jäljelle, minä annan pelokkaan sydämen heidän vihollistensa maassa, niin että lentävän lehden kahina ajaa heidät pakoon. He pakenevat, niin kuin pakenisivat miekkaa, ja kaatuvat, vaikka ei kukaan aja heitä takaa.',
        37: 'He kompastuvat toisiinsa kuin miekkaa paeten, vaikka ei kukaan aja heitä takaa, ettekä voi pitää puolianne vihollisianne vastaan.',
        38: 'Te häviätte kansojen sekaan, ja vihollistenne maa nielee teidät.',
        39: 'Ne teistä, jotka jäävät jäljelle, riutuvat vihollistenne maassa syntivelkansa tähden. Myös isiensä syntivelan tähden he riutuvat kuten hekin.',
        40: 'Silloin he tunnustavat syntivelkansa ja isiensä syntivelan, sen että ovat olleet minulle uskottomat ja käyneet minua vastaan,',
        41: 'jonka tähden minäkin kävin heitä vastaan ja vein heidät heidän vihollistensa maahan. Silloin heidän ympärileikkaamaton sydämensä nöyrtyy, ja silloin he sovittavat syntivelkansa.',
        42: 'Silloin minä muistan liittoni Jaakobin kanssa ja muistan liittoni Iisakin kanssa ja liittoni Aabrahamin kanssa, ja minä muistan myös maata.',
        43: 'Mutta ensin tulkoon maa tyhjäksi heistä ja saakoon hyvityksen sapateistaan olemalla autiona, niin kauan kuin he ovat poissa. Sovittakoot syntivelkansa sen tähden, juuri sen tähden, että he hylkäsivät säädökseni ja että heidän sielunsa luopui käskyistäni.',
        44: 'Mutta sittenkään, vaikka he ovat vihollistensa maassa, en minä heitä hylkää enkä hylkää heitä niin, että tekisin heistä lopun ja rikkoisin liittoni heidän kanssaan, sillä minä olen Herra, heidän Jumalansa.',
        45: 'Minä muistan heidän hyväkseen liiton heidän isiensä kanssa, jotka minä vein pois Egyptin maasta pakanakansojen silmien edessä, ollakseni heidän Jumalansa. Minä olen Herra."',
        46: 'Nämä ovat ne käskyt, säädökset ja lait, jotka Herra asetti itsensä ja israelilaisten välille Siinain vuorella Mooseksen kautta.',
    },
    27: {
        1: 'Herra puhui Moosekselle sanoen:',
        2: '"Puhu israelilaisille ja sano heille: Jos jollakin on täytettävänä lupaus Herralle ja sinun on arvioitava luvatun ihmisen arvo,',
        3: 'niin arvioi mies, joka on kahdenkymmenen ja kuudenkymmenen vuoden välillä, viiteenkymmeneen hopeasekeliin pyhäkkösekelin painon mukaan.',
        4: 'Mutta jos se on nainen, arvioi hänet kolmeenkymmeneen sekeliin.',
        5: 'Viisivuotiaasta kaksikymmenvuotiaaseen asti arvioi miespuoli kahteenkymmeneen sekeliin ja naispuoli kymmeneen sekeliin.',
        6: 'Kuukauden vanhasta viisivuotiaaseen asti arvioi miespuoli viiteen hopeasekeliin ja naispuoli kolmeen hopeasekeliin.',
        7: 'Kuusikymmenvuotias ja sitä vanhempi miespuoli arvioi viiteentoista sekeliin ja naispuoli kymmeneen sekeliin.',
        8: 'Jos joku on liian köyhä maksamaan arviohintaa, vietäköön hänet papin eteen, ja pappi arvioikoon hänet. Pappi arvioikoon hänet lupauksen tekijän varallisuuden mukaan.',
        9: 'Jos lupaus sen sijaan koskee karjaa, josta voidaan tuoda uhrilahja Herralle, olkoon kaikki, mikä siitä annetaan Herralle, pyhää.',
        10: 'Älköön sitä vaihdettako älköönkä muutettako, ei hyvää huonoon eikä huonoa hyvään. Jos joku kuitenkin vaihtaa eläimen toiseen, olkoon sekä se että siihen vaihdettu pyhä.',
        11: 'Mutta jos se on saastainen eläin, mikä tahansa, joita ei saa tuoda uhrilahjaksi Herralle, vietäköön eläin papin eteen.',
        12: 'Pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.',
        13: 'Jos omistaja tahtoo sen lunastaa, antakoon arviohinnan lisäksi viidennen osan siitä.',
        14: 'Jos joku pyhittää talonsa pyhäksi lahjaksi Herralle, pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.',
        15: 'Mutta jos se, joka on talonsa pyhittänyt, tahtoo lunastaa sen, niin antakoon arviosumman lisäksi viidennen osan siitä. Niin se on hänen omansa.',
        16: 'Jos joku pyhittää Herralle kappaleen perintömaataan, niin arvioi se kylvön suuruuden mukaan. Hoomer-mitta ohria vastatkoon viittäkymmentä hopeasekeliä.',
        17: 'Jos hän pyhittää peltonsa riemuvuodesta alkaen, jääköön sille arvioimasi täysi hinta.',
        18: 'Mutta jos hän pyhittää peltonsa riemuvuoden jälkeen, laskekoon pappi hänelle rahasumman niiden vuosien luvun mukaan, jotka ovat jäljellä seuraavaan riemuvuoteen. Vähennettäköön se arvioimastasi hinnasta.',
        19: 'Jos se, joka on pellon pyhittänyt, tahtoo lunastaa sen, niin antakoon arvioimasi hinnan lisäksi viidennen osan siitä, ja niin se jää hänen omakseen.',
        20: 'Mutta jos hän ei lunasta peltoa, vaan myy sen toiselle, se ei ole enää lunastettavissa.',
        21: 'Kun pelto riemuvuotena tulee vapaaksi, olkoon se Herralle pyhitetty, niin kuin vihitty pelto. Se tulee papin omaisuudeksi.',
        22: 'Jos joku pyhittää Herralle ostamansa pellon, joka ei ole hänen perintömaataan,',
        23: 'laskekoon pappi hänelle arviohinnan riemuvuoteen asti. Suorittakoon hän samana päivänä arvioimasi hinnan pyhänä lahjana Herralle.',
        24: 'Riemuvuotena pelto palautukoon sille, jolta se on ostettu ja jonka perintömaata se on.',
        25: 'Kaikki arvioimisesi tapahtukoon pyhäkkösekelin painon mukaan. Sekelissä olkoon kaksikymmentä geeraa.',
        26: 'Mutta karjan esikoista, joka ensiksi syntyneenä on jo Herralle tuleva, älköön kukaan pyhittäkö, olipa se härkä tai lammas. Se on jo Herran.',
        27: 'Jos se on saastaisia eläimiä, lunastakoon omistaja sen arvioimastasi hinnasta ja pankoon lisäksi viidennen osan sen arvosta. Jos sitä ei lunasteta, myytäköön se arvioimaasi hintaan.',
        28: 'Mitään vihittyä, mitä hyvänsä, jonka joku on vihkinyt Herralle omaisuudestaan, olipa se ihminen, eläin tai perintömaa, älköön myytäkö älköönkä lunastettako. Kaikki vihitty on näet korkeasti pyhää, Herralle tulevaa.',
        29: 'Ihmistä, ketä hyvänsä, joka on tuhon omaksi vihitty, älköön lunastettako, vaan hänet surmattakoon.',
        30: 'Kaikki maan kymmenykset, sekä pellon viljasta että puiden hedelmistä, ovat Herran. Ne ovat pyhä lahja Herralle.',
        31: 'Jos joku tahtoo lunastaa jotakin kymmenyksistään, antakoon siihen lisäksi viidennen osan.',
        32: 'Kaikki kymmenykset nautakarjasta ja lampaista ja vuohista, sekä joka kymmenes eläin kaikesta, mikä kulkee paimenen sauvan ali, olkoot pyhiä lahjoja Herralle.',
        33: 'Älköön kysyttäkö, onko se hyvä vai huono, älköönkä sitä vaihdettako. Jos joku kuitenkin vaihtaa sen, olkoon sekä se että siihen vaihdettu pyhä. Älköön niitä lunastettako."',
        34: 'Nämä ovat ne käskyt, jotka Herra Siinain vuorella antoi Moosekselle israelilaisia varten.',
    },
}
